const ensureRectVisibilityDraft = (obj) => {
  if (!obj || (obj.type !== "rect" && obj.type !== "line" && obj.type !== "ellipse" && obj.type !== "text" && obj.type !== "button" && obj.type !== "group" && obj.type !== "circle" && obj.type !== "polygon")) return;
  if (rectVisibilityDraftObject !== obj || !rectVisibilityDraft) {
    rectVisibilityDraftObject = obj;
    rectVisibilityDraft = cloneVisibilityState(obj.visibility || { enabled: true });
  }
};

const ensureRectColorDraft = (obj) => {
  if (!obj || (obj.type !== "rect" && obj.type !== "line" && obj.type !== "ellipse" && obj.type !== "text" && obj.type !== "button" && obj.type !== "circle" && obj.type !== "polygon" && obj.type !== "group")) return;
  if (rectColorDraftObject !== obj || !rectColorDraft) {
    const rules = buildColorRulesFromObject(obj);
    rectColorDraftObject = obj;
    rectColorDraft = cloneRectColorDraft({ rules, selectedRuleIndex: 0 });
    rectColorDraft = normalizeRectColorDraft(obj, rectColorDraft);
  }
};

const ensureRectRotationDraft = (obj) => {
  if (!obj || (obj.type !== "rect" && obj.type !== "line" && obj.type !== "ellipse" && obj.type !== "text" && obj.type !== "button" && obj.type !== "group")) return;
  if (rectRotationDraftObject !== obj || !rectRotationDraft) {
    rectRotationDraftObject = obj;
    rectRotationDraft = cloneRectRotationDraft({
      pivotMode: normalizePivotMode(obj.pivotMode, obj.type),
      pivotX: obj.pivotX,
      pivotY: obj.pivotY,
      rotationAutomation: normalizeRotationAutomationState(obj.rotationAutomation || { enabled: true })
    });
  }
};

const ensureRectMotionDraft = (obj) => {
  if (!obj || (obj.type !== "rect" && obj.type !== "line" && obj.type !== "ellipse" && obj.type !== "text" && obj.type !== "button" && obj.type !== "circle" && obj.type !== "group")) return;
  if (rectMotionDraftObject !== obj || !rectMotionDraft) {
    rectMotionDraftObject = obj;
    rectMotionDraft = cloneRectMotionDraft(normalizeMotionAutomationState({
      ...(obj.motion || {}),
      enabled: obj.motion?.enabled !== false
    }));
  }
};

const setObjectDynamicTab = (tab) => {
  const normalized = String(tab || "properties").trim();
  const next =
    normalized === "visibility" ? "visibility" :
    isColorDynamicTab(normalized) ? getColorDynamicTabKey(getColorDynamicTabIndex(normalized)) :
    normalized === "states" ? "states" :
    normalized === "rotation" ? "rotation" :
    normalized === "motion" ? "motion" :
    "properties";
  currentObjectDynamicTab = next;
  if (isColorDynamicTab(next)) {
    const obj = getSelectedColorDynamicObject();
    if (obj && rectColorDraftObject === obj && rectColorDraft) {
      rectColorDraft = {
        ...rectColorDraft,
        selectedRuleIndex: Math.max(0, Math.min(getColorDynamicTabIndex(next), normalizeRectColorDraft(obj, rectColorDraft).rules.length - 1))
      };
    }
  }
  if (objectDynamicTabPropertiesBtn) objectDynamicTabPropertiesBtn.classList.toggle("is-active", next === "properties");
  if (objectDynamicTabVisibilityBtn) objectDynamicTabVisibilityBtn.classList.toggle("is-active", next === "visibility");
  if (objectDynamicTabStatesBtn) objectDynamicTabStatesBtn.classList.toggle("is-active", next === "states");
  if (objectDynamicTabRotationBtn) objectDynamicTabRotationBtn.classList.toggle("is-active", next === "rotation");
  if (objectDynamicTabMotionBtn) objectDynamicTabMotionBtn.classList.toggle("is-active", next === "motion");
  syncObjectDynamicColorTabs(getSelectedColorDynamicObject());
};

const syncObjectDynamicColorTabs = (obj) => {
  if (!objectDynamicTabs || !objectDynamicTabColorBtn) return;
  const count = hasEditableColorDynamic(obj) ? getCurrentColorRulesForObject(obj).length : 0;
  const existing = [...objectDynamicTabs.querySelectorAll("[data-color-tab-index]")];
  existing.forEach((button) => {
    const index = Number(button.getAttribute("data-color-tab-index") || "0");
    if (index <= 0 || index < count) return;
    button.remove();
  });
  if (count <= 0) {
    objectDynamicTabColorBtn.classList.add("is-hidden");
    objectDynamicTabColorBtn.hidden = true;
    return;
  }
  objectDynamicTabColorBtn.classList.remove("is-hidden");
  objectDynamicTabColorBtn.hidden = false;
  objectDynamicTabColorBtn.textContent = "Color";
  objectDynamicTabColorBtn.dataset.colorTabIndex = "0";
  objectDynamicTabColorBtn.dataset.objectDynamicTab = "color";
  for (let index = 1; index < count; index += 1) {
    let button = objectDynamicTabs.querySelector(`[data-color-tab-index="${index}"]`);
    if (!button) {
      button = objectDynamicTabColorBtn.cloneNode(true);
      button.id = "";
      (objectDynamicTabStatesBtn || objectDynamicTabRotationBtn)?.before(button);
    }
    button.classList.remove("is-hidden");
    button.hidden = false;
    button.textContent = `Color ${index + 1}`;
    button.dataset.colorTabIndex = String(index);
    button.dataset.objectDynamicTab = getColorDynamicTabKey(index);
  }
  [...objectDynamicTabs.querySelectorAll("[data-color-tab-index]")].forEach((button) => {
    const tabKey = String(button.dataset.objectDynamicTab || "color");
    button.classList.toggle("is-active", currentObjectDynamicTab === tabKey);
  });
};

const getPropertiesPaneTitle = (obj) => {
  if (!obj) return "Properties";
  const type = String(obj.type || "").trim();
  switch (type) {
    case "text": return "Text Properties";
    case "button": return "Button Properties";
    case "group": return "Group Properties";
    case "viewport": return "Viewport Properties";
    case "rect": return "Rectangle Properties";
    case "alarms-panel": return "Alarm Panel Properties";
    case "ellipse": return "Ellipse Properties";
    case "circle": return "Circle Properties";
    case "line": return "Line Properties";
    case "curve": return "Curve Properties";
    case "polyline": return "Polyline Properties";
    case "spline": return "Spline Properties";
    case "polygon": return "Polygon Properties";
    case "bar": return "Bar Properties";
    case "number-input": return "Number Input Properties";
    case "indicator": return "Indicator Properties";
    case "image": return "Image Properties";
    default: return "Properties";
  }
};

const ensureVisibilityDynamicForSelectedObject = () => {
  const activeObjects = getActiveObjects();
  const obj = getSelectedVisibilityDynamicObject();
  if (!activeObjects || !obj || selectedIndices.length !== 1) return false;
  if (!hasVisibilityDynamic(obj)) {
    recordHistory();
    obj.visibility = { enabled: true };
    renderScreen();
    syncEditorFromScreen();
    setDirty(true);
  }
  ensureRectVisibilityDraft(obj);
  currentObjectDynamicTab = "visibility";
  updatePropertiesPanel();
  return true;
};

const ensureRectColorDynamic = () => {
  const activeObjects = getActiveObjects();
  const obj = getSelectedColorDynamicObject();
  if (!activeObjects || !obj || selectedIndices.length !== 1) return false;
  const hadDraftForObject = rectColorDraftObject === obj && Boolean(rectColorDraft);
  ensureRectColorDraft(obj);
  const storedRuleCount = buildColorRulesFromObject(obj).length;
  const draft = normalizeRectColorDraft(obj, rectColorDraft);
  if (storedRuleCount > 0 || hadDraftForObject) {
    draft.rules.push({ ...getDefaultColorRuleForObject(obj) });
  }
  const nextIndex = Math.max(0, draft.rules.length - 1);
  draft.selectedRuleIndex = nextIndex;
  rectColorDraft = draft;
  currentObjectDynamicTab = getColorDynamicTabKey(nextIndex);
  updatePropertiesPanel();
  return true;
};

const ensureRectRotationDynamic = () => {
  const activeObjects = getActiveObjects();
  const obj = getSelectedRotationDynamicObject();
  if (!activeObjects || !obj || selectedIndices.length !== 1) return false;
  if (!(hasRectRotationDynamic(obj) || hasLineRotationDynamic(obj) || hasEllipseRotationDynamic(obj) || hasTextRotationDynamic(obj) || hasButtonRotationDynamic(obj) || hasGroupRotationDynamic(obj))) {
    recordHistory();
    obj.rotationAutomation = { enabled: true, inputMin: 0, inputMax: 1, angleStart: 0, angleEnd: 0, direction: "shortest" };
    renderScreen();
    syncEditorFromScreen();
    setDirty(true);
  }
  ensureRectRotationDraft(obj);
  currentObjectDynamicTab = "rotation";
  updatePropertiesPanel();
  return true;
};

const ensureMultiStateDynamic = () => {
  const activeObjects = getActiveObjects();
  const obj = getSelectedMultiStateDynamicObject();
  if (!activeObjects || !obj || selectedIndices.length !== 1) return false;
  if (!hasMultiStateDynamic(obj)) {
    recordHistory();
    obj.multiStateAutomation = normalizeMultiStateAutomationState({});
    renderScreen();
    syncEditorFromScreen();
    setDirty(true);
  }
  currentObjectDynamicTab = "states";
  updatePropertiesPanel();
  return true;
};

const ensureRectMotionDynamic = () => {
  const activeObjects = getActiveObjects();
  const obj = getSelectedMotionDynamicObject();
  if (!activeObjects || !obj || selectedIndices.length !== 1) return false;
  if (!(hasRectMotionDynamic(obj) || hasLineMotionDynamic(obj) || hasEllipseMotionDynamic(obj) || hasTextMotionDynamic(obj) || hasButtonMotionDynamic(obj) || hasCircleMotionDynamic(obj) || hasGroupMotionDynamic(obj))) {
    recordHistory();
    obj.motion = { enabled: true, inputMin: 0, inputMax: 1 };
    renderScreen();
    syncEditorFromScreen();
    setDirty(true);
  }
  ensureRectMotionDraft(obj);
  currentObjectDynamicTab = "motion";
  updatePropertiesPanel();
  return true;
};

const getMotionControlForObject = (obj) => motionControlConfigs.find((control) => obj && control.types.includes(obj.type)) || null;
const getRotationControlForObject = (obj) => rotationControlConfigs.find((control) => obj && control.types.includes(obj.type)) || null;
const supportsAutomationPanelForObject = (obj) => Boolean(obj && (visibilityProps || getMotionControlForObject(obj) || getRotationControlForObject(obj)));
const getAutomationSectionsForObjectByTab = (obj, tab) => automationSectionConfigs.filter((config) => obj && config.tab === tab && config.types.includes(obj.type));

const returnAutomationSectionsToStore = () => {
  if (!automationPanelStore) return;
  [
    automationTabPanelMotion,
    automationTabPanelRotation,
    automationTabPanelVisibility,
    automationTabPanelText,
    automationTabPanelColor,
    automationTabPanelFill,
    automationTabPanelStroke,
    automationTabPanelValue
  ].forEach((panel) => {
    if (!panel) return;
    while (panel.firstChild) automationPanelStore.appendChild(panel.firstChild);
  });
};

const setAutomationTab = (nextTab) => {
  const tab = String(nextTab || "").trim();
  const buttons = [
    { id: "motion", el: automationTabMotionBtn, panel: automationTabPanelMotion },
    { id: "rotation", el: automationTabRotationBtn, panel: automationTabPanelRotation },
    { id: "visibility", el: automationTabVisibilityBtn, panel: automationTabPanelVisibility },
    { id: "text", el: automationTabTextBtn, panel: automationTabPanelText },
    { id: "color", el: automationTabColorBtn, panel: automationTabPanelColor },
    { id: "fill", el: automationTabFillBtn, panel: automationTabPanelFill },
    { id: "stroke", el: automationTabStrokeBtn, panel: automationTabPanelStroke },
    { id: "value", el: automationTabValueBtn, panel: automationTabPanelValue }
  ];
  const available = buttons.filter((entry) => entry.el && !entry.el.classList.contains("is-hidden"));
  const wants = available.some((entry) => entry.id === tab) ? tab : (available[0]?.id || "visibility");
  currentAutomationTab = wants;
  buttons.forEach((entry) => {
    const active = entry.id === wants && available.some((option) => option.id === entry.id);
    if (entry.el) {
      entry.el.classList.toggle("is-active", active);
      entry.el.setAttribute("aria-selected", active ? "true" : "false");
    }
    if (entry.panel) entry.panel.classList.toggle("is-hidden", !active);
  });
  const obj = getAutomationObject();
  if (obj) lastAutomationTabByType.set(String(obj.type || ""), wants);
};

const populateAutomationPanel = () => {
  if (!automationPanel || !automationPanelStore) return;
  returnAutomationSectionsToStore();
  const obj = getAutomationObject();
  if (!obj || !supportsAutomationPanelForObject(obj)) {
    closeAutomationPanel();
    return;
  }
  if (automationPanelTitle) automationPanelTitle.textContent = `Automation — ${String(obj.type || "Object")}`;
  const motionControl = getMotionControlForObject(obj);
  const rotationControl = getRotationControlForObject(obj);
  const visibilityAvailable = Boolean(visibilityProps);
  if (motionControl?.sectionEl && automationTabPanelMotion) {
    motionControl.sectionEl.classList.remove("is-hidden");
    automationTabPanelMotion.appendChild(motionControl.sectionEl);
  }
  if (rotationControl?.sectionEl && automationTabPanelRotation) {
    rotationControl.sectionEl.classList.remove("is-hidden");
    automationTabPanelRotation.appendChild(rotationControl.sectionEl);
  }
  if (visibilityAvailable && automationTabPanelVisibility) {
    visibilityProps.classList.remove("is-hidden");
    automationTabPanelVisibility.appendChild(visibilityProps);
  }
  [["text", automationTabPanelText], ["color", automationTabPanelColor], ["fill", automationTabPanelFill], ["stroke", automationTabPanelStroke], ["value", automationTabPanelValue]].forEach(([tab, panel]) => {
    if (!panel) return;
    getAutomationSectionsForObjectByTab(obj, tab).forEach((config) => {
      if (config.sectionEl) {
        config.sectionEl.classList.remove("is-hidden");
        panel.appendChild(config.sectionEl);
      }
    });
  });
  if (automationTabMotionBtn) automationTabMotionBtn.classList.toggle("is-hidden", !motionControl?.sectionEl);
  if (automationTabRotationBtn) automationTabRotationBtn.classList.toggle("is-hidden", !rotationControl?.sectionEl);
  if (automationTabVisibilityBtn) automationTabVisibilityBtn.classList.toggle("is-hidden", !visibilityAvailable);
  if (automationTabTextBtn) automationTabTextBtn.classList.toggle("is-hidden", getAutomationSectionsForObjectByTab(obj, "text").length === 0);
  if (automationTabColorBtn) automationTabColorBtn.classList.toggle("is-hidden", getAutomationSectionsForObjectByTab(obj, "color").length === 0);
  if (automationTabFillBtn) automationTabFillBtn.classList.toggle("is-hidden", getAutomationSectionsForObjectByTab(obj, "fill").length === 0);
  if (automationTabStrokeBtn) automationTabStrokeBtn.classList.toggle("is-hidden", getAutomationSectionsForObjectByTab(obj, "stroke").length === 0);
  if (automationTabValueBtn) automationTabValueBtn.classList.toggle("is-hidden", getAutomationSectionsForObjectByTab(obj, "value").length === 0);
  const preferredTab = lastAutomationTabByType.get(String(obj.type || "")) || currentAutomationTab;
  setAutomationTab(preferredTab);
};

const openAutomationPanel = () => {
  const obj = getAutomationObject();
  if (!isEditMode || !obj || !supportsAutomationPanelForObject(obj) || !automationPanel) return;
  automationPanelPrevEditorVisible = Boolean(editorPane && !editorPane.classList.contains("is-hidden"));
  if (editorPane) editorPane.classList.add("is-hidden");
  document.body.classList.add("automation-panel-open");
  automationPanel.classList.remove("is-hidden");
  automationPanel.setAttribute("aria-hidden", "false");
  automationPanelOpen = true;
  populateAutomationPanel();
};

const closeAutomationPanel = () => {
  if (!automationPanel) return;
  automationPanel.classList.add("is-hidden");
  automationPanel.setAttribute("aria-hidden", "true");
  returnAutomationSectionsToStore();
  automationPanelOpen = false;
  document.body.classList.remove("automation-panel-open");
  if (editorPane && isEditMode && automationPanelPrevEditorVisible) {
    editorPane.classList.remove("is-hidden");
    applyEditorPaneState(getEditorPaneState() || { dock: "right" });
  }
  automationPanelPrevEditorVisible = false;
};

// Screen Files (Open / Save As)
let screenFileMode = "open"; // "open" | "saveAs"
let screenFileSource = "screens"; // "screens" | "images"
let screenFileDir = "";
let screenFileSelected = null; // { kind:"dir"|"file", name, path, ref }
let screenFileHistory = [];
let screenFileHistoryIndex = -1;
let screenFileUploadTargetSource = "screens";
let screenFileUploadTargetDir = "";

const screenFileDateFormatter = new Intl.DateTimeFormat(undefined, {
  year: "numeric",
  month: "short",
  day: "numeric",
  hour: "numeric",
  minute: "2-digit"
});

const updateScreenFileFooterButtons = () => {
  const isScreens = screenFileSource === "screens";
  const isImages = screenFileSource === "images";
  const canDownload = screenFileMode === "open"
    && Boolean(screenFileSelected)
    && (
      (isScreens && ((screenFileSelected?.kind === "file" && Boolean(screenFileSelected?.path)) || screenFileSelected?.kind === "dir"))
      || (isImages && screenFileSelected?.kind === "file" && Boolean(screenFileSelected?.name))
    );
  if (screenFileDownloadBtn) screenFileDownloadBtn.disabled = !canDownload;
  const canOpen = isScreens && screenFileSelected?.kind === "file" && Boolean(screenFileSelected?.path);
  const canManageFile = screenFileSelected?.kind === "file";
  if (screenFilePrimaryBtn) screenFilePrimaryBtn.disabled = screenFileMode === "open" ? !canOpen : !isScreens;
  if (screenFileOpenBtn) screenFileOpenBtn.disabled = !canOpen;
  if (screenFileUploadBtn) screenFileUploadBtn.disabled = screenFileMode !== "open";
  if (screenFileRenameBtn) screenFileRenameBtn.disabled = !canManageFile;
  if (screenFileDuplicateBtn) screenFileDuplicateBtn.disabled = !canManageFile;
  if (screenFileDeleteBtn) screenFileDeleteBtn.disabled = !canManageFile;
  if (screenFileNewBtn) screenFileNewBtn.disabled = !isScreens;
  if (screenFileNewFolderBtn) screenFileNewFolderBtn.disabled = !isScreens;
  if (screenFileBackBtn) screenFileBackBtn.disabled = !(screenFileHistoryIndex > 0);
  if (screenFileForwardBtn) screenFileForwardBtn.disabled = !(screenFileHistoryIndex >= 0 && screenFileHistoryIndex < screenFileHistory.length - 1);
  if (screenFileUpBtn) screenFileUpBtn.disabled = !isScreens || !normalizeDirForUi(screenFileDir);
};

const formatScreenFileSize = (bytes) => {
  const value = Number(bytes);
  if (!Number.isFinite(value) || value < 0) return "—";
  if (value < 1024) return `${value} B`;
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(value < 10 * 1024 ? 1 : 0)} KB`;
  return `${(value / (1024 * 1024)).toFixed(value < 10 * 1024 * 1024 ? 1 : 0)} MB`;
};

const formatScreenFileModified = (mtimeMs) => {
  const value = Number(mtimeMs);
  if (!Number.isFinite(value) || value <= 0) return "—";
  return screenFileDateFormatter.format(new Date(value));
};

const updateScreenFileSelectionSummary = () => {
  if (!screenFileSelectionSummary) return;
  if (!screenFileSelected) {
    screenFileSelectionSummary.textContent = screenFileMode === "saveAs" && screenFileSource === "screens"
      ? "Choose a folder and enter a file name."
      : "No file selected.";
    return;
  }
  if (screenFileSelected.kind === "dir") {
    screenFileSelectionSummary.textContent = `Folder: ${screenFileSelected.path || screenFileSelected.name || ""}`;
    return;
  }
  const file = screenFileSelected;
  const parts = [
    file.path || file.name || "",
    `Modified ${formatScreenFileModified(file.mtimeMs)}`,
    `Size ${formatScreenFileSize(file.size)}`
  ].filter(Boolean);
  screenFileSelectionSummary.textContent = parts.join(" • ");
};

const normalizeDirForUi = (dir) => {
  const trimmed = String(dir || "").replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/g, "");
  return trimmed;
};

const pathBasename = (p) => String(p || "").replace(/\\/g, "/").split("/").pop() || "";
const screenRefFromPath = (relPath) => String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "").replace(/\.(screen|jsonc)$/i, "");

const setScreenFileDialogMode = (mode) => {
  screenFileMode = mode === "saveAs" ? "saveAs" : "open";
  if (screenFileTitle) screenFileTitle.textContent = screenFileMode === "saveAs" ? "Save Screen As…" : "File Manager";
  if (screenFilePrimaryBtn) screenFilePrimaryBtn.textContent = screenFileMode === "saveAs" ? "Save" : "Open";
  if (screenFileNameInput) screenFileNameInput.disabled = false;
  if (screenFileNameRow) screenFileNameRow.classList.toggle("is-hidden", screenFileMode !== "saveAs" || screenFileSource !== "screens");
  if (screenFileOpenBtn) screenFileOpenBtn.classList.toggle("is-hidden", screenFileMode !== "open");
  if (screenFileUploadBtn) screenFileUploadBtn.classList.toggle("is-hidden", screenFileMode !== "open");
  if (screenFileDownloadBtn) screenFileDownloadBtn.classList.toggle("is-hidden", screenFileMode !== "open");
  if (screenFileUploadInput) {
    screenFileUploadInput.value = "";
    if (screenFileSource === "images") {
      screenFileUploadInput.accept = ".png,.jpg,.jpeg,.gif,.webp,.bmp,.svg,image/*";
      screenFileUploadInput.multiple = true;
    } else {
      screenFileUploadInput.accept = ".screen,.jsonc,application/json,text/plain";
      screenFileUploadInput.multiple = true;
    }
  }
  updateScreenFileSelectionSummary();
  updateScreenFileFooterButtons();
};

const fetchScreenDir = async (dir) => {
  const norm = normalizeDirForUi(dir);
  const url = norm ? `/api/screens/list?dir=${encodeURIComponent(norm)}` : "/api/screens/list";
  const resp = await fetch(url);
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
  return await resp.json();
};

const fetchImageManagerList = async () => {
  const resp = await fetch("/api/img-files", { cache: "no-store" });
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
  return await resp.json();
};

const renderScreenFileTree = (payload) => {
  if (!screenFileTree) return;
  screenFileTree.innerHTML = "";

  const buildNode = (name, source, relDir, hasChildrenHint = true) => {
    const wrap = document.createElement("div");
    const row = document.createElement("div");
    row.className = "screen-file-tree-item";
    row.dataset.dir = relDir;
    row.dataset.source = source;

    const toggle = document.createElement("span");
    toggle.className = "screen-file-tree-toggle";
    toggle.textContent = "▸";
    if (!hasChildrenHint) toggle.classList.add("is-hidden");

    const label = document.createElement("span");
    label.textContent = name;

    row.appendChild(toggle);
    row.appendChild(label);

    const children = document.createElement("div");
    children.className = "screen-file-tree-children is-hidden";

    const setActive = () => {
      screenFileTree.querySelectorAll(".screen-file-tree-item").forEach((el) => el.classList.remove("is-active"));
      row.classList.add("is-active");
    };

    const ensureChildrenLoaded = async () => {
      if (children.dataset.loaded === "1") return;
      children.dataset.loaded = "1";
      if (source !== "screens") {
        toggle.classList.add("is-hidden");
        return;
      }
      try {
        const next = await fetchScreenDir(relDir);
        const dirs = next?.dirs || [];
        if (!dirs.length) {
          toggle.classList.add("is-hidden");
          return;
        }
        dirs.forEach((childName) => {
          const nextRel = relDir ? `${relDir}/${childName}` : childName;
          const node = buildNode(childName, "screens", nextRel, true);
          children.appendChild(node);
        });
      } catch {
        // ignore
      }
    };

    toggle.addEventListener("click", async (e) => {
      e.stopPropagation();
      const isHidden = children.classList.contains("is-hidden");
      if (isHidden) {
        await ensureChildrenLoaded();
        children.classList.remove("is-hidden");
        toggle.textContent = "▾";
      } else {
        children.classList.add("is-hidden");
        toggle.textContent = "▸";
      }
    });

    row.addEventListener("click", async () => {
      setActive();
      screenFileSelected = { kind: "dir", source, name, path: relDir };
      updateScreenFileFooterButtons();
      updateScreenFileSelectionSummary();
      await setScreenFileLocation({ source, dir: relDir }, { push: true });
    });

    row.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      setActive();
      screenFileSelected = { kind: "dir", source, name, path: relDir };
      updateScreenFileFooterButtons();
      updateScreenFileSelectionSummary();
      showScreenFileContextMenu(event.clientX, event.clientY, { kind: "dir", source, name, path: relDir });
    });

    wrap.appendChild(row);
    wrap.appendChild(children);
    return wrap;
  };

  const screensRoot = buildNode("screens", "screens", "", true);
  screenFileTree.appendChild(screensRoot);
  const imagesRoot = buildNode("images", "images", "", false);
  screenFileTree.appendChild(imagesRoot);
  const screensRootToggle = screensRoot.querySelector(".screen-file-tree-toggle");
  if (screensRootToggle) screensRootToggle.click();

  // Highlight current dir if possible
  window.setTimeout(() => {
    const target = normalizeDirForUi(screenFileDir);
    const selector = `.screen-file-tree-item[data-source=\"${CSS.escape(screenFileSource)}\"][data-dir=\"${CSS.escape(target)}\"]`;
    const active = screenFileTree.querySelector(selector);
    if (active) active.classList.add("is-active");
  }, 0);
};

const renderScreenFileList = (payload) => {
  if (!openFileList) return;
  openFileList.innerHTML = "";
  screenFileSelected = null;
  const dir = normalizeDirForUi(payload?.dir);
  screenFileDir = dir;
  renderScreenBreadcrumb(dir);
  updateScreenFileNavButtons();
  updateScreenFileFooterButtons();

  const addItem = (kind, label, meta) => {
    const item = document.createElement("div");
    item.className = "open-file-item";
    item.dataset.kind = kind;
    if (meta?.path) item.dataset.path = meta.path;
    if (meta?.ref) item.dataset.ref = meta.ref;
    if (kind === "file" && currentScreenPath && String(meta?.path || "") === String(currentScreenPath)) {
      item.classList.add("is-current");
      item.title = "Current screen";
    }

    const nameCell = document.createElement("div");
    nameCell.className = "open-file-item-name";
    nameCell.textContent = label;
    const modifiedCell = document.createElement("div");
    modifiedCell.className = "open-file-item-modified";
    modifiedCell.textContent = kind === "file" ? formatScreenFileModified(meta?.mtimeMs) : "Folder";
    const sizeCell = document.createElement("div");
    sizeCell.className = "open-file-item-size";
    sizeCell.textContent = kind === "file" ? formatScreenFileSize(meta?.size) : "—";
    item.appendChild(nameCell);
    item.appendChild(modifiedCell);
    item.appendChild(sizeCell);

    item.addEventListener("click", () => {
      openFileList.querySelectorAll(".open-file-item").forEach((el) => el.classList.remove("is-selected"));
      item.classList.add("is-selected");
      screenFileSelected = { kind, ...meta };
      if (kind === "file" && screenFileNameInput && screenFileMode === "saveAs") {
        screenFileNameInput.value = meta?.name || "";
      }
      updateScreenFileFooterButtons();
      updateScreenFileSelectionSummary();
    });

    item.addEventListener("dblclick", () => {
      if (kind === "dir") {
        setScreenFileLocation({ source: "screens", dir: meta?.path || "" }, { push: true });
        return;
      }
      if (kind === "file" && screenFileMode === "open") {
        openSelectedScreenFile();
      }
    });

    item.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      item.click();
      showScreenFileContextMenu(event.clientX, event.clientY, { kind, source: "screens", ...meta });
    });

    openFileList.appendChild(item);
  };

  (payload?.dirs || []).forEach((name) => {
    const clean = String(name || "").trim();
    if (!clean) return;
    const nextPath = dir ? `${dir}/${clean}` : clean;
    addItem("dir", `📁 ${clean}`, { name: clean, path: nextPath });
  });

  (payload?.files || []).forEach((file) => {
    const name = String(file?.name || "").trim();
    if (!name) return;
    addItem("file", name, { name, path: file.path, ref: file.ref, size: file.size, mtimeMs: file.mtimeMs });
  });
  updateScreenFileSelectionSummary();
};

const renderImageFileList = (payload) => {
  if (!openFileList) return;
  openFileList.innerHTML = "";
  screenFileSelected = null;
  screenFileDir = "";
  renderScreenBreadcrumb("");
  const addItem = (file) => {
    const item = document.createElement("div");
    item.className = "open-file-item";
    item.dataset.kind = "file";
    item.dataset.source = "images";
    item.dataset.name = file.name;
    const nameCell = document.createElement("div");
    nameCell.className = "open-file-item-name";
    nameCell.textContent = file.name;
    const modifiedCell = document.createElement("div");
    modifiedCell.className = "open-file-item-modified";
    modifiedCell.textContent = formatScreenFileModified(file.mtimeMs);
    const sizeCell = document.createElement("div");
    sizeCell.className = "open-file-item-size";
    sizeCell.textContent = formatScreenFileSize(file.size);
    item.appendChild(nameCell);
    item.appendChild(modifiedCell);
    item.appendChild(sizeCell);
    item.addEventListener("click", () => {
      openFileList.querySelectorAll(".open-file-item").forEach((el) => el.classList.remove("is-selected"));
      item.classList.add("is-selected");
      screenFileSelected = { kind: "file", source: "images", name: file.name, size: file.size, mtimeMs: file.mtimeMs };
      updateScreenFileFooterButtons();
      updateScreenFileSelectionSummary();
    });
    item.addEventListener("contextmenu", (event) => {
      event.preventDefault();
      item.click();
      showScreenFileContextMenu(event.clientX, event.clientY, { kind: "file", source: "images", name: file.name, size: file.size, mtimeMs: file.mtimeMs });
    });
    openFileList.appendChild(item);
  };
  (payload?.items || []).forEach(addItem);
  updateScreenFileFooterButtons();
  updateScreenFileSelectionSummary();
};

const showFixedContextMenuAt = (menu, clientX, clientY) => {
  if (!menu) return;
  const margin = 8;
  menu.style.left = `${margin}px`;
  menu.style.top = `${margin}px`;
  menu.classList.remove("is-hidden");
  const rect = menu.getBoundingClientRect();
  const maxLeft = Math.max(margin, window.innerWidth - rect.width - margin);
  const maxTop = Math.max(margin, window.innerHeight - rect.height - margin);
  const left = Math.min(Math.max(margin, Number(clientX) || margin), maxLeft);
  const top = Math.min(Math.max(margin, Number(clientY) || margin), maxTop);
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
};

const ensureScreenFileContextMenu = () => {
  if (screenFileContextMenu) return screenFileContextMenu;
  const menu = document.createElement("div");
  menu.className = "hmi-context-menu is-hidden";
  menu.setAttribute("role", "menu");
  menu.addEventListener("click", (event) => {
    event.stopPropagation();
  });
  document.body.appendChild(menu);
  screenFileContextMenu = menu;

  const closeIfOpen = () => {
    if (!screenFileContextMenuOpen) return;
    screenFileContextMenuOpen = false;
    menu.classList.add("is-hidden");
    menu.innerHTML = "";
  };

  document.addEventListener("click", closeIfOpen);
  window.addEventListener("blur", closeIfOpen);
  window.addEventListener("keydown", (evt) => {
    if (evt.key === "Escape") closeIfOpen();
  });

  return menu;
};

const showScreenFileContextMenu = (clientX, clientY, target) => {
  if (!target) return;
  const menu = ensureScreenFileContextMenu();
  screenFileContextMenuOpen = true;
  menu.innerHTML = "";

  const title = document.createElement("div");
  title.className = "hmi-context-menu-title";
  title.textContent = String(target.name || target.path || target.source || "Item");
  menu.appendChild(title);

  const addItem = (label, onClick, disabled = false) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "hmi-context-menu-item";
    btn.textContent = label;
    btn.disabled = disabled;
    btn.addEventListener("click", async () => {
      try {
        await onClick?.();
      } finally {
        screenFileContextMenuOpen = false;
        menu.classList.add("is-hidden");
        menu.innerHTML = "";
      }
    });
    menu.appendChild(btn);
  };

  if (target.kind === "dir") {
    addItem("Open", async () => {
      await setScreenFileLocation({ source: target.source, dir: target.path || "" }, { push: true });
    });
    if (target.source === "screens") {
      addItem("Upload Here…", async () => {
        if (!screenFileUploadInput) return;
        screenFileUploadInput.value = "";
        screenFileUploadInput.accept = ".screen,.jsonc,application/json,text/plain";
        screenFileUploadInput.multiple = true;
        screenFileUploadTargetSource = "screens";
        screenFileUploadTargetDir = target.path || "";
        screenFileUploadInput.click();
      });
      addItem("Download Folder…", async () => {
        downloadScreenManagerEntry(target, "screens");
      });
    } else {
      addItem("Upload Here…", async () => {
        if (!screenFileUploadInput) return;
        screenFileUploadInput.value = "";
        screenFileUploadInput.accept = ".png,.jpg,.jpeg,.gif,.webp,.bmp,.svg,image/*";
        screenFileUploadInput.multiple = true;
        screenFileUploadTargetSource = "images";
        screenFileUploadTargetDir = "";
        screenFileUploadInput.click();
      });
    }
    addItem("Cancel", async () => {});
  } else if (target.kind === "file") {
    if (target.source === "screens") {
      addItem("Open", async () => {
        screenFileSelected = target;
        await openSelectedScreenFile();
      });
    }
    addItem("Download…", async () => {
      downloadScreenManagerEntry(target, target.source || screenFileSource);
    });
    addItem("Rename", async () => {
      screenFileSelected = target;
      await renameSelectedScreenFile();
    });
    addItem("Duplicate", async () => {
      screenFileSelected = target;
      await duplicateSelectedScreenFile();
    });
    addItem("Delete", async () => {
      screenFileSelected = target;
      await deleteSelectedScreenFile();
    });
    addItem("Cancel", async () => {});
  }

  showFixedContextMenuAt(menu, clientX, clientY);
};

const navigateScreenFileLocation = async (source, dir) => {
  try {
    screenFileSource = source === "images" ? "images" : "screens";
    if (screenFileSource === "images") {
      const payload = await fetchImageManagerList();
      renderScreenFileTree();
      renderImageFileList(payload);
      setScreenFileDialogMode(screenFileMode);
      return;
    }
    const payload = await fetchScreenDir(dir);
    renderScreenFileTree(payload);
    renderScreenFileList(payload);
    setScreenFileDialogMode(screenFileMode);
  } catch (error) {
    setEditorStatusSafe(`Failed to list screens: ${error.message}`);
  }
};

const pushScreenFileHistory = ({ source, dir }) => {
  const entry = { source: source === "images" ? "images" : "screens", dir: normalizeDirForUi(dir) };
  const current = screenFileHistoryIndex >= 0 ? screenFileHistory[screenFileHistoryIndex] : null;
  if (current && current.source === entry.source && current.dir === entry.dir) return;
  screenFileHistory = screenFileHistory.slice(0, screenFileHistoryIndex + 1);
  screenFileHistory.push(entry);
  screenFileHistoryIndex = screenFileHistory.length - 1;
};

const setScreenFileLocation = async ({ source, dir }, { push = true } = {}) => {
  const entry = { source: source === "images" ? "images" : "screens", dir: normalizeDirForUi(dir) };
  if (push) pushScreenFileHistory(entry);
  await navigateScreenFileLocation(entry.source, entry.dir);
};

const renderScreenBreadcrumb = (dir) => {
  if (!screenFileBreadcrumb) return;
  screenFileBreadcrumb.innerHTML = "";
  if (screenFileSource === "images") {
    const root = document.createElement("span");
    root.className = "screen-file-crumb";
    root.textContent = "images";
    root.title = "/public/img";
    root.addEventListener("click", () => {
      setScreenFileLocation({ source: "images", dir: "" }, { push: true });
    });
    screenFileBreadcrumb.appendChild(root);
    return;
  }
  const parts = normalizeDirForUi(dir).split("/").filter(Boolean);
  const rootCrumb = document.createElement("span");
  rootCrumb.className = "screen-file-crumb";
  rootCrumb.textContent = "screens";
  rootCrumb.title = "/ (screens root)";
  rootCrumb.addEventListener("click", () => {
    setScreenFileLocation({ source: "screens", dir: "" }, { push: true });
  });
  screenFileBreadcrumb.appendChild(rootCrumb);
  parts.forEach((part, idx) => {
    const sep = document.createElement("span");
    sep.className = "screen-file-sep";
    sep.textContent = "›";
    screenFileBreadcrumb.appendChild(sep);
    const crumb = document.createElement("span");
    crumb.className = "screen-file-crumb";
    crumb.textContent = part;
    const to = parts.slice(0, idx + 1).join("/");
    crumb.title = `/${to}`;
    crumb.addEventListener("click", () => {
      setScreenFileLocation({ source: "screens", dir: to }, { push: true });
    });
    screenFileBreadcrumb.appendChild(crumb);
  });
};

const updateScreenFileNavButtons = () => {
  updateScreenFileFooterButtons();
};

const showScreenFileDialog = async (mode) => {
  if (!openFileOverlay) return;
  if (mode === "saveAs") screenFileSource = "screens";
  screenFileUploadTargetSource = screenFileSource;
  screenFileUploadTargetDir = screenFileDir || "";
  setScreenFileDialogMode(mode);
  openFileOverlay.classList.remove("is-hidden");
  if (screenFileNameInput && mode === "saveAs") {
    const base = currentScreenPath ? pathBasename(currentScreenPath).replace(/\.(screen|jsonc)$/i, "") : "";
    screenFileNameInput.value = base;
    window.setTimeout(() => screenFileNameInput.focus(), 0);
  }
  if (mode === "saveAs" && currentScreenPath) {
    const parts = String(currentScreenPath || "").replace(/\\/g, "/").split("/").filter(Boolean);
    parts.pop();
    screenFileDir = parts.join("/");
  }
  pushScreenFileHistory({ source: screenFileSource, dir: screenFileDir || "" });
  await navigateScreenFileLocation(screenFileSource, screenFileDir || "");
};

const hideScreenFileDialog = () => {
  if (!openFileOverlay) return;
  const activeEl = document.activeElement;
  if (activeEl instanceof HTMLElement && openFileOverlay.contains(activeEl)) {
    try { activeEl.blur(); } catch {}
  }
  openFileOverlay.classList.add("is-hidden");
};

const openTagsModal = () => {
  if (!tagsModalOverlay) return;
  setMenuOpen(false);
  if (viewMenuFlyout) viewMenuFlyout.classList.add("is-hidden");
  if (viewMenuBtn) viewMenuBtn.setAttribute("aria-expanded", "false");
  tagsModalOverlay.classList.remove("is-hidden");
  tagsModalOverlay.setAttribute("aria-hidden", "false");
  try { tagsFilterInput?.focus?.(); } catch {}
};

const closeTagsModal = () => {
  if (!tagsModalOverlay) return;
  tagsModalOverlay.classList.add("is-hidden");
  tagsModalOverlay.setAttribute("aria-hidden", "true");
};

// Standalone Library modal: reuse the existing library panel DOM (temporary).
let libraryPanelOriginalParent = null;
let libraryPanelOriginalNextSibling = null;

const openLibraryModal = () => {
  if (!libraryModalOverlay || !libraryModalHost) return;
  const panel = document.querySelector('.editor-panel[data-panel="library"]');
  if (!panel) return;
  setMenuOpen(false);
  if (insertMenuFlyout) insertMenuFlyout.classList.add("is-hidden");
  if (insertMenuBtn) insertMenuBtn.setAttribute("aria-expanded", "false");

  if (!libraryPanelOriginalParent) {
    libraryPanelOriginalParent = panel.parentElement;
    libraryPanelOriginalNextSibling = panel.nextSibling;
  }

  libraryModalHost.innerHTML = "";
  panel.dataset._prevDisplay = panel.style.display || "";
  panel.dataset._prevActive = panel.classList.contains("is-active") ? "1" : "0";
  panel.style.display = "block";
  panel.classList.add("is-active");
  libraryModalHost.appendChild(panel);

  libraryModalOverlay.classList.remove("is-hidden");
  libraryModalOverlay.setAttribute("aria-hidden", "false");
};

const closeLibraryModal = () => {
  if (!libraryModalOverlay) return;
  const panel = document.querySelector('.editor-panel[data-panel="library"]');
  if (panel && libraryPanelOriginalParent) {
    const prevDisplay = panel.dataset._prevDisplay;
    if (prevDisplay !== undefined) panel.style.display = prevDisplay;
    const prevActive = panel.dataset._prevActive;
    if (prevActive === "0") panel.classList.remove("is-active");
    delete panel.dataset._prevDisplay;
    delete panel.dataset._prevActive;
    if (libraryPanelOriginalNextSibling && libraryPanelOriginalParent.contains(libraryPanelOriginalNextSibling)) {
      libraryPanelOriginalParent.insertBefore(panel, libraryPanelOriginalNextSibling);
    } else {
      libraryPanelOriginalParent.appendChild(panel);
    }
  }
  libraryModalOverlay.classList.add("is-hidden");
  libraryModalOverlay.setAttribute("aria-hidden", "true");
};

const openSelectedScreenFile = async () => {
  if (screenFileSource !== "screens") return;
  let nextPath = "";
  if (screenFileSelected?.kind === "file") {
    nextPath = String(screenFileSelected.path || "").trim();
  } else {
    const typed = String(screenFileNameInput?.value || "").trim();
    if (typed) {
      nextPath = normalizeDirForUi(screenFileDir) ? `${normalizeDirForUi(screenFileDir)}/${typed}` : typed;
    }
  }
  if (!nextPath) return;
  applyScreenSelection(screenRefFromPath(nextPath), nextPath);
  hideScreenFileDialog();
};

const createNewUnsavedScreen = () => {
  if (isDirty && !confirmLoseUnsavedChanges("New screen")) {
    showHmiToast("New screen canceled (unsaved changes kept).", 6000);
    return false;
  }
  currentScreenPath = "";
  currentScreenId = "untitled";
  currentScreenFilename = "untitled.screen";
  lastLoadedFilename = "";
  selectedIndices = [];
  clearSelectedPolygonVertex();
  if (screenTitle) screenTitle.textContent = "Untitled";
  if (editorFilename) editorFilename.textContent = currentScreenFilename;
  loadJsonc();
  return true;
};

const downloadScreenManagerEntry = (entry = screenFileSelected, source = screenFileSource) => {
  if (screenFileMode !== "open") return;
  if (!entry) return;
  if (source === "images") {
    const filename = String(entry.name || "").trim();
    if (!filename) return;
    window.location.href = `/api/img-files/${encodeURIComponent(filename)}/download`;
    return;
  }
  if (entry.kind === "dir") {
    const dir = normalizeDirForUi(entry.path || "");
    const url = dir
      ? `/api/screens/folder/download?dir=${encodeURIComponent(dir)}`
      : "/api/screens/folder/download";
    window.location.href = url;
    return;
  }
  const relPath = String(entry.path || "").trim();
  if (!relPath) return;
  window.location.href = `/api/screens/file/download?path=${encodeURIComponent(relPath)}`;
};

const saveScreenToPath = async (relPath, raw) => {
  const response = await fetch(`/api/screens/file?path=${encodeURIComponent(relPath)}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ raw })
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return await response.json();
};

const getCurrentScreenRawForSave = () => {
  if (!jsoncEditor) return "";
  blurActiveFormControl();
  if (currentTab === "jsonc") return jsoncEditor.value;
  if (!currentScreenObj) return jsoncEditor.value;
  const raw = JSON.stringify(currentScreenObj, null, 2);
  jsoncEditor.value = raw;
  jsonEditorSyncPending = false;
  return raw;
};

const saveCurrentScreenAs = async () => {
  if (!jsoncEditor) return;
  const baseDir = normalizeDirForUi(screenFileDir);
  const nameRaw = String(screenFileNameInput?.value || "").trim();
  if (!nameRaw) {
    setEditorStatusSafe("Enter a file name.");
    return;
  }
  const filename = nameRaw;
  const relPath = baseDir ? `${baseDir}/${filename}` : filename;
  try {
    const saved = await saveScreenToPath(relPath, getCurrentScreenRawForSave());
    currentScreenPath = saved.path;
    currentScreenId = saved.ref;
    currentScreenFilename = pathBasename(currentScreenPath);
    if (screenTitle) screenTitle.textContent = currentScreenId || "Untitled";
    if (editorFilename) editorFilename.textContent = currentScreenFilename;
    await refreshScreensList();
    hideScreenFileDialog();
    setDirty(false);
    setEditorStatusSafe(`Saved ${currentScreenFilename}.`);
  } catch (error) {
    setEditorStatusSafe(`Save failed: ${error.message}`);
  }
};

const uploadScreenManagerFiles = async (files, { source = screenFileSource, dir = screenFileDir } = {}) => {
  const uploads = Array.from(files || []);
  if (!uploads.length) return;
  if (source === "images") {
    setEditorStatusSafe(`Uploading ${uploads.length} image(s)…`);
    for (const file of uploads) {
      await uploadImageFile(file);
    }
    await loadImageFiles();
    await navigateScreenFileLocation("images", "");
    setEditorStatusSafe(`Uploaded ${uploads.length} image(s).`);
    return;
  }
  const baseDir = normalizeDirForUi(dir);
  setEditorStatusSafe(`Uploading ${uploads.length} screen file(s)…`);
  for (const file of uploads) {
    const raw = await file.text();
    const filename = pathBasename(String(file?.name || "").trim());
    if (!filename) continue;
    const relPath = baseDir ? `${baseDir}/${filename}` : filename;
    await saveScreenToPath(relPath, raw);
  }
  await refreshScreensList();
  await navigateScreenFileLocation("screens", dir);
  setEditorStatusSafe(`Uploaded ${uploads.length} screen file(s).`);
};

const renameSelectedScreenFile = async () => {
  if (!screenFileSelected || screenFileSelected.kind !== "file") return;
  if (screenFileSelected.source === "images") {
    const oldName = String(screenFileSelected.name || "").trim();
    if (!oldName) return;
    const nextName = window.prompt("Rename image file:", oldName);
    if (nextName == null) return;
    const trimmed = String(nextName || "").trim();
    if (!trimmed || trimmed === oldName) return;
    try {
      const response = await fetch("/api/img-files/rename", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ oldName, newName: trimmed })
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const saved = await response.json();
      await navigateScreenFileLocation("images", "");
      screenFileSelected = { kind: "file", source: "images", name: saved.filename };
      updateScreenFileFooterButtons();
      updateScreenFileSelectionSummary();
    } catch (error) {
      setEditorStatusSafe(`Rename failed: ${error.message}`);
    }
    return;
  }
  const oldPath = String(screenFileSelected.path || "").trim();
  if (!oldPath) return;
  const currentName = pathBasename(oldPath);
  const nextName = window.prompt("Rename screen file:", currentName);
  if (nextName == null) return;
  const trimmed = String(nextName || "").trim();
  if (!trimmed || trimmed === currentName) return;
  const baseDir = normalizeDirForUi(screenFileDir);
  const newPath = baseDir ? `${baseDir}/${trimmed}` : trimmed;
  try {
    const response = await fetch("/api/screens/rename", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ oldPath, newPath })
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const saved = await response.json();
    if (currentScreenPath === oldPath) {
      currentScreenPath = saved.path;
      currentScreenId = saved.ref;
      currentScreenFilename = pathBasename(saved.path);
      if (screenTitle) screenTitle.textContent = currentScreenId || "Untitled";
      if (editorFilename) editorFilename.textContent = currentScreenFilename;
    }
    await refreshScreensList();
    await navigateScreenFileLocation("screens", screenFileDir);
    screenFileSelected = { kind: "file", name: pathBasename(saved.path), path: saved.path, ref: saved.ref };
    if (screenFileNameInput) screenFileNameInput.value = pathBasename(saved.path);
    updateScreenFileFooterButtons();
    updateScreenFileSelectionSummary();
  } catch (error) {
    setEditorStatusSafe(`Rename failed: ${error.message}`);
  }
};

const duplicateSelectedScreenFile = async () => {
  if (!screenFileSelected || screenFileSelected.kind !== "file") return;
  if (screenFileSelected.source === "images") {
    const sourceName = String(screenFileSelected.name || "").trim();
    if (!sourceName) return;
    const ext = pathBasename(sourceName).match(/(\.[^.]+)$/)?.[1] || "";
    const baseName = ext ? sourceName.slice(0, -ext.length) : sourceName;
    const suggested = `${baseName} Copy${ext}`;
    const nextName = window.prompt("Duplicate image as:", suggested);
    if (nextName == null) return;
    const trimmed = String(nextName || "").trim();
    if (!trimmed) return;
    try {
      const response = await fetch("/api/img-files/duplicate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sourceName, targetName: trimmed })
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const saved = await response.json();
      await navigateScreenFileLocation("images", "");
      screenFileSelected = { kind: "file", source: "images", name: saved.filename };
      updateScreenFileFooterButtons();
      updateScreenFileSelectionSummary();
    } catch (error) {
      setEditorStatusSafe(`Duplicate failed: ${error.message}`);
    }
    return;
  }
  const sourcePath = String(screenFileSelected.path || "").trim();
  if (!sourcePath) return;
  const currentName = pathBasename(sourcePath);
  const extMatch = currentName.match(/(\.(screen|jsonc))$/i);
  const ext = extMatch ? extMatch[1] : ".screen";
  const baseName = currentName.replace(/(\.(screen|jsonc))$/i, "");
  const suggested = `${baseName} Copy${ext}`;
  const nextName = window.prompt("Duplicate screen as:", suggested);
  if (nextName == null) return;
  const trimmed = String(nextName || "").trim();
  if (!trimmed) return;
  const baseDir = normalizeDirForUi(screenFileDir);
  const targetPath = baseDir ? `${baseDir}/${trimmed}` : trimmed;
  try {
    const response = await fetch("/api/screens/duplicate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ sourcePath, targetPath })
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const saved = await response.json();
    await refreshScreensList();
    await navigateScreenFileLocation("screens", screenFileDir);
    screenFileSelected = { kind: "file", name: pathBasename(saved.path), path: saved.path, ref: saved.ref };
    if (screenFileNameInput) screenFileNameInput.value = pathBasename(saved.path);
    updateScreenFileFooterButtons();
    updateScreenFileSelectionSummary();
  } catch (error) {
    setEditorStatusSafe(`Duplicate failed: ${error.message}`);
  }
};

const deleteSelectedScreenFile = async () => {
  if (!screenFileSelected || screenFileSelected.kind !== "file") return;
  if (screenFileSelected.source === "images") {
    const filename = String(screenFileSelected.name || "").trim();
    if (!filename) return;
    if (!window.confirm(`Delete image file "${filename}"?`)) return;
    try {
      const response = await fetch(`/api/img-files/${encodeURIComponent(filename)}`, { method: "DELETE" });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      screenFileSelected = null;
      await navigateScreenFileLocation("images", "");
      updateScreenFileFooterButtons();
      updateScreenFileSelectionSummary();
    } catch (error) {
      setEditorStatusSafe(`Delete failed: ${error.message}`);
    }
    return;
  }
  const relPath = String(screenFileSelected.path || "").trim();
  if (!relPath) return;
  const filename = pathBasename(relPath);
  if (!window.confirm(`Delete screen file \"${filename}\"?`)) return;
  try {
    const response = await fetch(`/api/screens/file?path=${encodeURIComponent(relPath)}`, {
      method: "DELETE"
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    if (currentScreenPath === relPath) {
      currentScreenPath = "";
      currentScreenId = "untitled";
      currentScreenFilename = "untitled.screen";
      lastLoadedFilename = "";
      if (screenTitle) screenTitle.textContent = "Untitled";
      if (editorFilename) editorFilename.textContent = currentScreenFilename;
      loadJsonc();
    }
    await refreshScreensList();
    screenFileSelected = null;
    if (screenFileNameInput) screenFileNameInput.value = "";
    await navigateScreenFileLocation("screens", screenFileDir);
    updateScreenFileFooterButtons();
    updateScreenFileSelectionSummary();
  } catch (error) {
    setEditorStatusSafe(`Delete failed: ${error.message}`);
  }
};

const goUpOneScreenDir = async () => {
  if (screenFileSource !== "screens") return;
  const dir = normalizeDirForUi(screenFileDir);
  if (!dir) return;
  const parts = dir.split("/").filter(Boolean);
  parts.pop();
  await setScreenFileLocation({ source: "screens", dir: parts.join("/") }, { push: true });
};

