const splitMultiline = (value) => {
  const raw = String(value ?? "");
  return raw.split(/\r?\n/);
};

const decodeNbspEntities = (value) => (
  String(value ?? "").replace(/&nbsp;|&#160;|\$nbsp;/gi, "\u00A0")
);

const getTextMeasureCtx = () => {
  if (textMeasureCtx) return textMeasureCtx;
  const canvas = document.createElement("canvas");
  textMeasureCtx = canvas.getContext("2d");
  return textMeasureCtx;
};

const getMeasuredTextHeight = (lineCount, lineHeight, ascent, descent) => {
  const count = Math.max(1, Number(lineCount) || 1);
  return Math.ceil(Number(ascent || 0) + Number(descent || 0) + (Number(lineHeight || 0) * (count - 1)));
};

const measureTextBlock = (text, fontSize, isBold = false) => {
  const ctx = getTextMeasureCtx();
  const size = Number(fontSize) || 16;
  const lineHeight = size * TEXT_LINE_HEIGHT_FACTOR;
  ctx.font = `${isBold ? "700 " : ""}${size}px Arial, sans-serif`;
  const lines = splitMultiline(text);
  const metrics = lines.map((line) => ctx.measureText(line || " "));
  const widths = metrics.map((m) => m.width);
  const width = widths.length ? Math.ceil(Math.max(...widths)) : 0;
  const ascent = Math.max(
    0,
    ...metrics.map((m) => (Number.isFinite(m.actualBoundingBoxAscent) ? m.actualBoundingBoxAscent : size * 0.8))
  );
  const descent = Math.max(
    0,
    ...metrics.map((m) => (Number.isFinite(m.actualBoundingBoxDescent) ? m.actualBoundingBoxDescent : size * 0.2))
  );
  const singleLineHeight = Math.ceil(ascent + descent);
  const height = getMeasuredTextHeight(lines.length, lineHeight, ascent, descent);
  return { lines, width, height, lineHeight, fontSize: size, ascent, descent, singleLineHeight };
};

const wrapTextToWidth = (text, maxWidth, fontSize, isBold = false) => {
  const ctx = getTextMeasureCtx();
  const size = Number(fontSize) || 16;
  const lineHeight = size * TEXT_LINE_HEIGHT_FACTOR;
  ctx.font = `${isBold ? "700 " : ""}${size}px Arial, sans-serif`;
  const widthLimit = Math.max(1, Number(maxWidth) || 1);
  const sourceLines = splitMultiline(String(text || ""));
  const wrappedLines = [];

  const pushWrappedWord = (word) => {
    let remaining = String(word || "");
    while (remaining) {
      let slice = remaining;
      while (slice.length > 1 && ctx.measureText(slice).width > widthLimit) {
        slice = slice.slice(0, -1);
      }
      if (!slice) slice = remaining.charAt(0);
      wrappedLines.push(slice);
      remaining = remaining.slice(slice.length);
    }
  };

  sourceLines.forEach((rawLine) => {
    const line = String(rawLine || "");
    if (!line.trim()) {
      wrappedLines.push("");
      return;
    }
    const words = line.trim().split(/\s+/).filter(Boolean);
    let currentLine = "";
    words.forEach((word) => {
      const candidate = currentLine ? `${currentLine} ${word}` : word;
      if (ctx.measureText(candidate).width <= widthLimit) {
        currentLine = candidate;
        return;
      }
      if (currentLine) {
        wrappedLines.push(currentLine);
        currentLine = "";
      }
      if (ctx.measureText(word).width <= widthLimit) {
        currentLine = word;
        return;
      }
      pushWrappedWord(word);
    });
    if (currentLine || !words.length) wrappedLines.push(currentLine);
  });

  const metrics = wrappedLines.map((line) => ctx.measureText(line || " "));
  const widths = metrics.map((m) => m.width);
  const width = widths.length ? Math.ceil(Math.max(...widths)) : 0;
  const ascent = Math.max(
    0,
    ...metrics.map((m) => (Number.isFinite(m.actualBoundingBoxAscent) ? m.actualBoundingBoxAscent : size * 0.8))
  );
  const descent = Math.max(
    0,
    ...metrics.map((m) => (Number.isFinite(m.actualBoundingBoxDescent) ? m.actualBoundingBoxDescent : size * 0.2))
  );
  const singleLineHeight = Math.ceil(ascent + descent);
  const height = getMeasuredTextHeight(wrappedLines.length, lineHeight, ascent, descent);
  return { lines: wrappedLines, width, height, lineHeight, fontSize: size, ascent, descent, singleLineHeight };
};

const evalQuadratic = (p0, p1, p2, t) => {
  const mt = 1 - t;
  return (mt * mt * p0) + (2 * mt * t * p1) + (t * t * p2);
};

const getQuadraticBounds = (p0, p1, p2) => {
  const values = [p0, p2];
  const denom = (p0 - 2 * p1 + p2);
  if (denom !== 0) {
    const t = (p0 - p1) / denom;
    if (t > 0 && t < 1) values.push(evalQuadratic(p0, p1, p2, t));
  }
  const min = Math.min(...values);
  const max = Math.max(...values);
  return { min, max };
};

const applyMultilineSvgText = (textEl, lines, x, yStart, lineHeight) => {
  if (!textEl) return;
  const ns = "http://www.w3.org/2000/svg";
  textEl.textContent = "";
  lines.forEach((line, idx) => {
    const tspan = document.createElementNS(ns, "tspan");
    tspan.setAttribute("xml:space", "preserve");
    tspan.setAttribute("x", x);
    if (idx === 0) {
      tspan.setAttribute("y", yStart);
    } else {
      tspan.setAttribute("dy", lineHeight);
    }
    tspan.textContent = line === "" ? "\u00a0" : line;
    textEl.appendChild(tspan);
  });
};
const getTextBaselineStart = (blockTop, measured) => {
  const ascent = Number(measured?.ascent);
  const fallback = Number(measured?.fontSize || 16) * 0.8;
  return Number(blockTop || 0) + (Number.isFinite(ascent) ? ascent : fallback);
};
