const getWsUrl = () => {
  let host = String(opcbridgeConfig?.host || "").trim();
  const pageHost = window.location.hostname || "";
  if (!host || host === "127.0.0.1" || host === "localhost") {
    host = pageHost || host;
  }
  if (!host) return "";
  if (/^wss?:\/\//i.test(host)) return host;
  const port = Number(opcbridgeConfig?.wsPort) || 9000;
  return `ws://${host}:${port}`;
};

