const getAlarmsWsUrl = () => {
  let host = String(alarmsConfig?.host || "").trim();
  const pageHost = window.location.hostname || "";
  if (!host) host = String(opcbridgeConfig?.host || "").trim();
  if (!host || host === "127.0.0.1" || host === "localhost") {
    host = pageHost || host;
  }
  if (!host) return "";
  if (/^wss?:\/\//i.test(host)) return host;
  const port = Number(alarmsConfig?.wsPort) || 8086;
  return `ws://${host}:${port}`;
};

const scheduleAlarmsWsReconnect = () => {
  if (alarmsWsReconnectTimer) return;
  alarmsWsReconnectTimer = setTimeout(() => {
    alarmsWsReconnectTimer = null;
    connectAlarmsWebSocket();
  }, 3000);
};

const connectAlarmsWebSocket = () => {
  const nextUrl = getAlarmsWsUrl();
  alarmsWsCurrentUrl = nextUrl;

  if (alarmsWsClient) {
    alarmsWsClient.onopen = null;
    alarmsWsClient.onclose = null;
    alarmsWsClient.onerror = null;
    alarmsWsClient.onmessage = null;
    alarmsWsClient.close();
    alarmsWsClient = null;
  }

  alarmsWsConnected = false;
  scheduleAlarmsRender();

  // Always try to load history at least once, even if the WS can't connect (firewall, etc.).
  // This keeps the alarm overlay/panel useful without requiring a WS connection.
  loadAlarmTimelineFromHistory();
  loadAlarmsStateFromHttp();

  if (!nextUrl) return;

  try {
    alarmsWsClient = new WebSocket(nextUrl);
  } catch {
    scheduleAlarmsWsReconnect();
    return;
  }

  alarmsWsClient.onopen = () => {
    alarmsWsConnected = true;
    loadAlarmTimelineFromHistory();
    loadAlarmsStateFromHttp();
    scheduleAlarmsRender();
  };

  alarmsWsClient.onclose = () => {
    alarmsWsConnected = false;
    scheduleAlarmsRender();
    scheduleAlarmsWsReconnect();
  };

  alarmsWsClient.onerror = () => {
    alarmsWsConnected = false;
    scheduleAlarmsRender();
  };

  alarmsWsClient.onmessage = (event) => {
    try {
      const payload = JSON.parse(event.data);
      const type = String(payload?.type || "");
      if (type === "snapshot" && Array.isArray(payload?.alarms)) {
        alarmsStateById = new Map();
        payload.alarms.forEach((alarm) => {
          const id = String(alarm?.alarm_id || "");
          if (!id) return;
          alarmsStateById.set(id, alarm);
          // A snapshot may include many configured alarms, most of which will be inactive.
          // Only "seed" the timeline for active alarms so the on-screen panel shows
          // current actives immediately without flooding the list with every alarm.
          upsertTimelineFromAlarmState(alarm, { createIfMissing: Boolean(alarm?.active) });
        });
        scheduleAlarmsRender();
        return;
      }
      if (type === "alarm_state" && payload?.alarm) {
        const alarm = payload.alarm;
        const id = String(alarm?.alarm_id || "");
        if (id) alarmsStateById.set(id, alarm);
        upsertTimelineFromAlarmState(alarm, { createIfMissing: Boolean(alarm?.active) });
        scheduleAlarmsRender();
        return;
      }
      if (type === "alarm_event" && payload?.event) {
        alarmsEvents.push(payload.event);
        if (alarmsEvents.length > 400) alarmsEvents = alarmsEvents.slice(-300);
        upsertTimelineFromAlarmEvent(payload.event);
        scheduleAlarmsRender();
      }
    } catch {
      // ignore malformed payloads
    }
  };
};

const isTouchscreenRuntime = () => (!isEditMode && Boolean(hmiUiConfig?.touchscreenMode));
const isViewOnlyRuntime = () => (!isEditMode && (Boolean(hmiUiConfig?.viewOnlyMode) || !canWrite()));

const identityMatrix = () => ({ a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 });

const multiplyMatrix = (m1, m2) => ({
  a: m1.a * m2.a + m1.c * m2.b,
  b: m1.b * m2.a + m1.d * m2.b,
  c: m1.a * m2.c + m1.c * m2.d,
  d: m1.b * m2.c + m1.d * m2.d,
  e: m1.a * m2.e + m1.c * m2.f + m1.e,
  f: m1.b * m2.e + m1.d * m2.f + m1.f
});

const applyMatrixToPoint = (m, pt) => ({
  x: m.a * pt.x + m.c * pt.y + m.e,
  y: m.b * pt.x + m.d * pt.y + m.f
});

const parseSvgNumber = (raw) => {
  const value = typeof raw === "string" ? raw.trim() : raw;
  const parsed = typeof value === "number" ? value : parseFloat(String(value ?? ""));
  return Number.isFinite(parsed) ? parsed : null;
};

const parseTransform = (raw) => {
  const value = String(raw || "").trim();
  if (!value) return identityMatrix();
  const re = /([a-zA-Z]+)\s*\(([^)]*)\)/g;
  let match;
  let out = identityMatrix();
  while ((match = re.exec(value))) {
    const fn = match[1].toLowerCase();
    const nums = match[2]
      .split(/[\s,]+/)
      .map((x) => x.trim())
      .filter(Boolean)
      .map((x) => parseSvgNumber(x))
      .filter((n) => n != null);
    if (fn === "matrix" && nums.length >= 6) {
      out = multiplyMatrix(out, { a: nums[0], b: nums[1], c: nums[2], d: nums[3], e: nums[4], f: nums[5] });
      continue;
    }
    if (fn === "translate") {
      const tx = Number(nums[0] ?? 0) || 0;
      const ty = Number(nums[1] ?? 0) || 0;
      out = multiplyMatrix(out, { a: 1, b: 0, c: 0, d: 1, e: tx, f: ty });
      continue;
    }
    if (fn === "scale") {
      const sx = Number(nums[0] ?? 1);
      const sy = Number(nums[1] ?? nums[0] ?? 1);
      if (Number.isFinite(sx) && Number.isFinite(sy)) {
        out = multiplyMatrix(out, { a: sx, b: 0, c: 0, d: sy, e: 0, f: 0 });
      }
      continue;
    }
    if (fn === "rotate") {
      const deg = Number(nums[0] ?? 0) || 0;
      const rad = (deg * Math.PI) / 180;
      const cos = Math.cos(rad);
      const sin = Math.sin(rad);
      const cx = Number(nums[1] ?? 0) || 0;
      const cy = Number(nums[2] ?? 0) || 0;
      const translateTo = { a: 1, b: 0, c: 0, d: 1, e: cx, f: cy };
      const rotate = { a: cos, b: sin, c: -sin, d: cos, e: 0, f: 0 };
      const translateBack = { a: 1, b: 0, c: 0, d: 1, e: -cx, f: -cy };
      out = multiplyMatrix(out, multiplyMatrix(multiplyMatrix(translateTo, rotate), translateBack));
      continue;
    }
  }
  return out;
};

const parseStyleAttribute = (raw) => {
  const style = {};
  const value = String(raw || "");
  value.split(";").forEach((pair) => {
    const [k, v] = pair.split(":");
    if (!k || !v) return;
    style[k.trim().toLowerCase()] = v.trim();
  });
  return style;
};

const getSvgAttr = (el, name) => {
  if (!el) return "";
  const direct = el.getAttribute(name);
  if (direct != null && direct !== "") return direct;
  const styleMap = parseStyleAttribute(el.getAttribute("style"));
  return styleMap[name.toLowerCase()] ?? "";
};

const parseViewBox = (svgEl) => {
  const raw = String(svgEl?.getAttribute("viewBox") || "").trim();
  const nums = raw.split(/[\s,]+/).map(Number).filter((n) => Number.isFinite(n));
  if (nums.length === 4) return { minX: nums[0], minY: nums[1], width: nums[2], height: nums[3] };
  const w = Number(svgEl?.getAttribute("width"));
  const h = Number(svgEl?.getAttribute("height"));
  if (Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0) return { minX: 0, minY: 0, width: w, height: h };
  return { minX: 0, minY: 0, width: 0, height: 0 };
};

const svgUserToHmiPoint = (pt, viewBox, imageObj) => {
  const vbW = Number(viewBox?.width) || Number(imageObj?.w) || 1;
  const vbH = Number(viewBox?.height) || Number(imageObj?.h) || 1;
  const sx = (Number(imageObj?.w) || vbW) / vbW;
  const sy = (Number(imageObj?.h) || vbH) / vbH;
  return {
    x: Number(imageObj?.x ?? 0) + (pt.x - Number(viewBox?.minX ?? 0)) * sx,
    y: Number(imageObj?.y ?? 0) + (pt.y - Number(viewBox?.minY ?? 0)) * sy
  };
};

const almostZero = (n, eps = 1e-6) => Math.abs(n) <= eps;

const explodeSvgDocumentToObjects = (svgEl, imageObj) => {
  const viewBox = parseViewBox(svgEl);
  const vbW = Number(viewBox.width) || Number(imageObj?.w) || 1;
  const vbH = Number(viewBox.height) || Number(imageObj?.h) || 1;
  const sx = (Number(imageObj?.w) || vbW) / vbW;
  const sy = (Number(imageObj?.h) || vbH) / vbH;

  const out = [];
  const walk = (node, parentMatrix) => {
    if (!(node instanceof Element)) return;
    const nodeMatrix = parseTransform(node.getAttribute("transform"));
    const matrix = multiplyMatrix(parentMatrix, nodeMatrix);
    const tag = node.tagName.toLowerCase();

    const fill = getSvgAttr(node, "fill");
    const stroke = getSvgAttr(node, "stroke");
    const strokeWidthRaw = getSvgAttr(node, "stroke-width");
    const strokeWidth = parseSvgNumber(strokeWidthRaw);
    const strokeScale = (sx + sy) / 2;
    const scaledStrokeWidth = strokeWidth != null ? Math.max(0, strokeWidth * strokeScale) : null;

    const isAxisAligned = almostZero(matrix.b) && almostZero(matrix.c);

    if (tag === "rect") {
      if (!isAxisAligned) return;
      const x = parseSvgNumber(node.getAttribute("x")) ?? 0;
      const y = parseSvgNumber(node.getAttribute("y")) ?? 0;
      const w = parseSvgNumber(node.getAttribute("width")) ?? 0;
      const h = parseSvgNumber(node.getAttribute("height")) ?? 0;
      if (w <= 0 || h <= 0) return;
      const rx = parseSvgNumber(node.getAttribute("rx")) ?? 0;
      const topLeft = svgUserToHmiPoint(applyMatrixToPoint(matrix, { x, y }), viewBox, imageObj);
      const bottomRight = svgUserToHmiPoint(applyMatrixToPoint(matrix, { x: x + w, y: y + h }), viewBox, imageObj);
      out.push({
        type: "rect",
        x: Math.round(Math.min(topLeft.x, bottomRight.x)),
        y: Math.round(Math.min(topLeft.y, bottomRight.y)),
        w: Math.round(Math.abs(bottomRight.x - topLeft.x)),
        h: Math.round(Math.abs(bottomRight.y - topLeft.y)),
        rx: Number.isFinite(rx) ? Math.round(rx * strokeScale) : 0,
        fill: fill || "#3a3f4b",
        stroke: stroke || "none",
        strokeWidth: scaledStrokeWidth != null ? Math.max(0, Math.round(scaledStrokeWidth)) : 0
      });
      return;
    }

    if (tag === "circle" || tag === "ellipse") {
      const cx = parseSvgNumber(node.getAttribute("cx")) ?? 0;
      const cy = parseSvgNumber(node.getAttribute("cy")) ?? 0;
      const r = tag === "circle" ? (parseSvgNumber(node.getAttribute("r")) ?? 0) : null;
      const rx = tag === "ellipse" ? (parseSvgNumber(node.getAttribute("rx")) ?? 0) : r;
      const ry = tag === "ellipse" ? (parseSvgNumber(node.getAttribute("ry")) ?? 0) : r;
      if (rx == null || ry == null || rx <= 0 || ry <= 0) return;

      if (tag === "ellipse" && !isAxisAligned) return;

      const centerUser = applyMatrixToPoint(matrix, { x: cx, y: cy });
      const center = svgUserToHmiPoint(centerUser, viewBox, imageObj);
      const edgeXUser = applyMatrixToPoint(matrix, { x: cx + rx, y: cy });
      const edgeYUser = applyMatrixToPoint(matrix, { x: cx, y: cy + ry });
      const edgeX = svgUserToHmiPoint(edgeXUser, viewBox, imageObj);
      const edgeY = svgUserToHmiPoint(edgeYUser, viewBox, imageObj);
      const rX = Math.hypot(edgeX.x - center.x, edgeX.y - center.y);
      const rY = Math.hypot(edgeY.x - center.x, edgeY.y - center.y);
      if (!(rX > 0) || !(rY > 0)) return;

      if (tag === "ellipse" && Math.abs(rX - rY) > 0.5) return;

      const radius = (rX + rY) / 2;
      const localScale = (rx > 0 && ry > 0) ? ((rX / rx) + (rY / ry)) / 2 : strokeScale;
      const scaledStroke = strokeWidth != null ? Math.max(0, strokeWidth * localScale) : null;
      out.push({
        type: "circle",
        cx: Math.round(center.x),
        cy: Math.round(center.y),
        r: Math.round(radius),
        fill: fill === "none" ? "none" : (fill || "#3a3f4b"),
        stroke: stroke === "none" ? "none" : (stroke || "none"),
        strokeWidth: scaledStroke != null ? Math.max(0, Math.round(scaledStroke)) : 0
      });
      return;
    }

    if (tag === "line") {
      const x1 = parseSvgNumber(node.getAttribute("x1")) ?? 0;
      const y1 = parseSvgNumber(node.getAttribute("y1")) ?? 0;
      const x2 = parseSvgNumber(node.getAttribute("x2")) ?? 0;
      const y2 = parseSvgNumber(node.getAttribute("y2")) ?? 0;
      const p1 = svgUserToHmiPoint(applyMatrixToPoint(matrix, { x: x1, y: y1 }), viewBox, imageObj);
      const p2 = svgUserToHmiPoint(applyMatrixToPoint(matrix, { x: x2, y: y2 }), viewBox, imageObj);
      out.push({
        type: "line",
        x1: Math.round(p1.x),
        y1: Math.round(p1.y),
        x2: Math.round(p2.x),
        y2: Math.round(p2.y),
        stroke: stroke || "#ffffff",
        strokeWidth: scaledStrokeWidth != null ? Math.max(0, Math.round(scaledStrokeWidth)) : 1
      });
      return;
    }

    if (tag === "polyline" || tag === "polygon") {
      const rawPoints = String(node.getAttribute("points") || "").trim();
      if (!rawPoints) return;
      const nums = rawPoints
        .split(/[\s,]+/)
        .map(parseSvgNumber)
        .filter((n) => n != null);
      if (nums.length < 4) return;
      const points = [];
      for (let i = 0; i < nums.length - 1; i += 2) {
        const pUser = applyMatrixToPoint(matrix, { x: nums[i], y: nums[i + 1] });
        const p = svgUserToHmiPoint(pUser, viewBox, imageObj);
        points.push({ x: Math.round(p.x), y: Math.round(p.y) });
      }
      if (tag === "polygon" && points.length >= 3) {
        out.push({
          type: "polygon",
          points,
          fill: fill || "#3a3f4b",
          stroke: stroke || "#ffffff",
          strokeWidth: scaledStrokeWidth != null ? Math.max(0, Math.round(scaledStrokeWidth)) : 1
        });
        return;
      }
      if (tag === "polyline" && points.length >= 2) {
        out.push({
          type: "polyline",
          points,
          stroke: stroke || "#ffffff",
          strokeWidth: scaledStrokeWidth != null ? Math.max(0, Math.round(scaledStrokeWidth)) : 2
        });
      }
      return;
    }

    if (tag === "text") {
      if (!isAxisAligned) return;
      const x = parseSvgNumber(node.getAttribute("x")) ?? 0;
      const y = parseSvgNumber(node.getAttribute("y")) ?? 0;
      const fontSizeRaw = getSvgAttr(node, "font-size");
      const fontSize = parseSvgNumber(fontSizeRaw);
      const p = svgUserToHmiPoint(applyMatrixToPoint(matrix, { x, y }), viewBox, imageObj);
      const text = String(node.textContent || "").trim();
      if (!text) return;
      out.push({
        type: "text",
        x: Math.round(p.x),
        y: Math.round(p.y),
        text,
        fontSize: fontSize != null ? Math.max(1, Math.round(fontSize * strokeScale)) : 18,
        fill: fill === "none" ? "none" : (fill || "#ffffff"),
        borderEnabled: false,
        borderStyle: "flat"
      });
      return;
    }

    Array.from(node.children).forEach((child) => walk(child, matrix));
  };

  Array.from(svgEl.children).forEach((child) => walk(child, identityMatrix()));
  return out;
};

const explodeSelectedSvgImage = async () => {
  if (!isEditMode) return;
  if (selectedIndices.length !== 1) return;
  const activeObjects = getActiveObjects() || [];
  const idx = selectedIndices[0];
  const obj = activeObjects[idx];
  if (!obj || obj.type !== "image") return;
  const src = String(obj.src || "").trim();
  if (!/\.svg$/i.test(src)) return;

  const response = await fetch(imgUrl(src), { cache: "no-store" });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const raw = await response.text();
  const doc = new DOMParser().parseFromString(raw, "image/svg+xml");
  const svgEl = doc.querySelector("svg");
  if (!svgEl) throw new Error("Invalid SVG.");
  const objects = explodeSvgDocumentToObjects(svgEl, obj);
  if (!objects.length) throw new Error("No supported primitives found.");

  recordHistory();
  const before = activeObjects.slice(0, idx);
  const after = activeObjects.slice(idx + 1);
  const nextObjects = before.concat(objects, after);
  setActiveObjects(nextObjects);
  selectedIndices = objects.map((_, i) => idx + i);
  renderScreen();
  syncEditorFromScreen();
  updateSelectionOverlays();
  updatePropertiesPanel();
  setDirty(true);
};

const translateObjectForExport = (obj, dx, dy) => {
  if (!obj || typeof obj !== "object") return;
  if (obj.type === "group") {
    if ("x" in obj) obj.x = Number(obj.x ?? 0) + dx;
    if ("y" in obj) obj.y = Number(obj.y ?? 0) + dy;
    return;
  }
  if (obj.type === "circle") {
    obj.cx = Number(obj.cx ?? 0) + dx;
    obj.cy = Number(obj.cy ?? 0) + dy;
    return;
  }
  if (obj.type === "line") {
    obj.x1 = Number(obj.x1 ?? 0) + dx;
    obj.y1 = Number(obj.y1 ?? 0) + dy;
    obj.x2 = Number(obj.x2 ?? 0) + dx;
    obj.y2 = Number(obj.y2 ?? 0) + dy;
    return;
  }
  if (obj.type === "polyline" || obj.type === "polygon" || obj.type === "spline") {
    const points = Array.isArray(obj.points) ? obj.points : [];
    obj.points = points.map((pt) => ({
      x: Number(pt?.x ?? 0) + dx,
      y: Number(pt?.y ?? 0) + dy
    }));
    return;
  }
  if ("x" in obj) obj.x = Number(obj.x ?? 0) + dx;
  if ("y" in obj) obj.y = Number(obj.y ?? 0) + dy;
};

const exportSelectionToSvgRaw = () => {
  if (!hmiSvg) return null;
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects) || !selectedIndices.length) return null;
  const bounds = getSelectionBoundsActive();
  if (!bounds) return null;
  const pad = 4;
  const width = Math.max(1, Math.ceil(Number(bounds.width ?? 0) + pad * 2));
  const height = Math.max(1, Math.ceil(Number(bounds.height ?? 0) + pad * 2));
  const dx = -(Number(bounds.x ?? 0)) + pad;
  const dy = -(Number(bounds.y ?? 0)) + pad;

  const ns = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(ns, "svg");
  svg.setAttribute("xmlns", ns);
  svg.setAttribute("width", String(width));
  svg.setAttribute("height", String(height));
  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);

  selectedIndices.forEach((idx) => {
    const obj = activeObjects[idx];
    if (!obj) return;
    const clone = JSON.parse(JSON.stringify(obj));
    translateObjectForExport(clone, dx, dy);
    renderObjectInto(svg, clone);
  });

  const serializer = new XMLSerializer();
  const raw = serializer.serializeToString(svg);
  const header = '<?xml version="1.0" encoding="UTF-8"?>\n';
  return header + raw + "\n";
};

const saveSvgToImageFolder = async (desiredName, raw) => {
  const name = String(desiredName || "").trim();
  if (!name) throw new Error("Missing filename.");
  const response = await fetch(`/api/svg-files/${encodeURIComponent(name)}`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ raw })
  });
  if (!response.ok) {
    const text = await response.text().catch(() => "");
    throw new Error(`HTTP ${response.status} ${text}`.trim());
  }
  return response.json().catch(() => ({ ok: true }));
};

const getBindPlaceholder = (bind) => {
  const digits = Number.isFinite(Number(bind?.digits)) ? Math.max(1, Math.trunc(Number(bind.digits))) : 1;
  const decimals = Number.isFinite(Number(bind?.decimals)) ? Math.max(0, Math.trunc(Number(bind.decimals))) : 0;
  const intDigits = Math.max(1, digits - decimals);
  const intPart = "?".repeat(intDigits);
  if (!decimals) return intPart;
  return `${intPart}.${"?".repeat(decimals)}`;
};

const TEXT_PLACEHOLDER_RE = /\{([a-zA-Z0-9_]+)\}/g;

const getTextPlaceholderKeys = (text) => {
  const source = String(text || "");
  const seen = new Set();
  const keys = [];
  for (const match of source.matchAll(TEXT_PLACEHOLDER_RE)) {
    const key = String(match[1] || "").trim();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    keys.push(key);
  }
  return keys;
};

const normalizeTextBinding = (bind) => {
  if (!bind || typeof bind !== "object") return null;
  const connection_id = String(bind.connection_id || "").trim();
  const tag = String(bind.tag || "").trim();
  const digits = Number.isFinite(Number(bind.digits)) ? Math.max(1, Math.trunc(Number(bind.digits))) : "";
  const padZeros = bind.padZeros === true || String(bind.padZeros || "").trim().toLowerCase() === "true";
  const decimals = Number.isFinite(Number(bind.decimals)) ? Math.max(0, Math.trunc(Number(bind.decimals))) : 0;
  const multiplier = Number.isFinite(Number(bind.multiplier)) ? Number(bind.multiplier) : 1;
  const hasValue = Boolean(connection_id || tag || digits !== "" || padZeros || decimals !== 0 || multiplier !== 1);
  if (!hasValue) return null;
  return { connection_id, tag, digits, padZeros, decimals, multiplier };
};

const getTextBindingsMap = (obj) => {
  const next = {};
  if (obj?.textBindings && typeof obj.textBindings === "object") {
    Object.entries(obj.textBindings).forEach(([key, bind]) => {
      const normalized = normalizeTextBinding(bind);
      if (normalized) next[String(key)] = normalized;
    });
  }
  if (!Object.keys(next).length) {
    const normalizedLegacy = normalizeTextBinding(obj?.bindText);
    if (normalizedLegacy) next.value = normalizedLegacy;
  }
  return next;
};

const getButtonLabelBindingsMap = (obj) => {
  const next = {};
  if (obj?.labelBindings && typeof obj.labelBindings === "object") {
    Object.entries(obj.labelBindings).forEach(([key, bind]) => {
      const normalized = normalizeTextBinding(bind);
      if (normalized) next[String(key)] = normalized;
    });
  }
  if (!Object.keys(next).length) {
    const normalizedLegacy = normalizeTextBinding(obj?.bindLabel);
    if (normalizedLegacy) next.value = normalizedLegacy;
  }
  return next;
};

const createInlineTextBindingRow = ({ key, binding, objectType = "text" }) => {
  const row = document.createElement("div");
  row.className = "text-binding-row text-binding-inline-row";

  const keyEl = document.createElement("div");
  keyEl.className = "text-binding-key";
  keyEl.textContent = `{${key}}`;

  const connectionInput = document.createElement("input");
  connectionInput.type = "text";
  connectionInput.className = "automation-tag-input";
  connectionInput.placeholder = "connection_id";
  connectionInput.value = String(binding?.connection_id || "");

  const tagInput = document.createElement("input");
  tagInput.type = "text";
  tagInput.className = "automation-tag-input";
  tagInput.placeholder = "tag";
  tagInput.value = String(binding?.tag || "");

  const editBtn = document.createElement("button");
  editBtn.type = "button";
  editBtn.className = "panel-btn";
  editBtn.textContent = "...";

  const applyPatch = (patch, options = {}) => {
    if (objectType === "button") updateButtonLabelBindingProperty(key, patch, options);
    else updateTextBindingProperty(key, patch, options);
  };

  connectionInput.addEventListener("change", () => {
    applyPatch({ connection_id: String(connectionInput.value || "").trim() });
  });
  tagInput.addEventListener("change", () => {
    applyPatch({ tag: String(tagInput.value || "").trim() });
  });
  editBtn.addEventListener("click", () => {
    openTextBindingModal(key, objectType);
  });

  row.append(keyEl, connectionInput, tagInput, editBtn);
  return row;
};

const renderBoundTemplate = (rawText, bindings, previewOnly = false) => {
  return String(rawText || "").replace(TEXT_PLACEHOLDER_RE, (_, key) => {
    const bind = bindings[String(key)] || null;
    if (!bind) return `{${String(key)}}`;
    const cacheKey = normalizeTagCacheKey(bind.connection_id, bind.tag);
    const rawValue = cacheKey ? tagValueCache.get(cacheKey) : undefined;
    return getTextBindingDisplayValue(rawValue, bind, previewOnly || isEditMode);
  });
};

const getTextBindingDisplayValue = (rawValue, bind, previewOnly = false) => {
  if (previewOnly) return getBindPlaceholder(bind);
  if (rawValue === undefined || rawValue === null || rawValue === "") return getBindPlaceholder(bind);
  const numericFormatted = formatBoundNumber(rawValue, bind);
  if (numericFormatted !== null) return numericFormatted;
  const text = String(rawValue);
  const digits = Number.isFinite(Number(bind?.digits)) ? Math.max(1, Math.trunc(Number(bind.digits))) : 0;
  if (digits <= 0) return text;
  return text.slice(0, digits);
};

const renderTextTemplate = (obj, previewOnly = false) => {
  const baseText = String(obj?.text || "");
  const bindings = getTextBindingsMap(obj);
  const multiStateText = getMultiStateTextOverride(obj);
  if (multiStateText !== null) return renderBoundTemplate(multiStateText, bindings, previewOnly);
  return getAutomationText(obj?.textStateAutomation, baseText, bindings, previewOnly);
};

const renderButtonLabelTemplate = (obj, previewOnly = false) => {
  return renderBoundTemplate(String(obj?.label || "Button"), getButtonLabelBindingsMap(obj), previewOnly);
};

const getTextBindingSummary = (bind) => {
  const normalized = normalizeTextBinding(bind);
  if (!normalized) return "(unbound)";
  const parts = [];
  const path = [normalized.connection_id, normalized.tag].filter(Boolean).join(" / ");
  parts.push(path || "(unbound)");
  if (normalized.digits !== "") parts.push(`digits=${normalized.digits}`);
  if (normalized.padZeros) parts.push("zpad");
  if (normalized.decimals) parts.push(`dec=${normalized.decimals}`);
  if (normalized.multiplier !== 1) parts.push(`x${normalized.multiplier}`);
  return parts.join(" · ");
};

const formatBoundNumber = (rawValue, bind) => {
  const numeric = Number(rawValue);
  if (!Number.isFinite(numeric)) return null;
  const multiplier = Number.isFinite(Number(bind?.multiplier)) ? Number(bind.multiplier) : 1;
  const digits = Number.isFinite(Number(bind?.digits)) ? Math.trunc(Number(bind.digits)) : 0;
  const padZeros = bind?.padZeros === true || String(bind?.padZeros || "").trim().toLowerCase() === "true";
  const decimals = Number.isFinite(Number(bind?.decimals)) ? Math.max(0, Math.trunc(Number(bind.decimals))) : 0;
  const scaled = numeric * multiplier;
  const fixed = scaled.toFixed(decimals);
  if (digits <= 0) return fixed;
  const [intPart, decPart] = fixed.split(".");
  const intDigits = Math.max(1, digits - decimals);
  const sign = intPart.startsWith("-") ? "-" : "";
  const unsignedInt = sign ? intPart.slice(1) : intPart;
  const fittedUnsignedInt = unsignedInt.length > intDigits
    ? unsignedInt.slice(unsignedInt.length - intDigits)
    : (padZeros ? unsignedInt.padStart(intDigits, "0") : unsignedInt);
  const fittedDecPart = decPart !== undefined
    ? decPart.slice(0, decimals)
    : undefined;
  const paddedInt = `${sign}${fittedUnsignedInt}`;
  return fittedDecPart !== undefined ? `${paddedInt}.${fittedDecPart}` : paddedInt;
};

const coerceTagBoolean = (value) => {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return value !== 0;
  if (typeof value === "string") {
    const trimmed = value.trim().toLowerCase();
    if (!trimmed) return false;
    if (["true", "on", "yes"].includes(trimmed)) return true;
    if (["false", "off", "no", "0"].includes(trimmed)) return false;
    const numeric = Number(trimmed);
    if (Number.isFinite(numeric)) return numeric !== 0;
    return true;
  }
  return Boolean(value);
};

const coerceTagNumber = (value) => {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "boolean") return value ? 1 : 0;
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return null;
    const numeric = Number(trimmed);
    return Number.isFinite(numeric) ? numeric : null;
  }
  return null;
};

const resolveBarLimit = (obj, which) => {
  const fallback = which === "max" ? 100 : 0;
  if (!obj) return fallback;
  const fixed = Number.isFinite(Number(obj[which])) ? Number(obj[which]) : fallback;
  if (isEditMode) return fixed;
  const binding = which === "max" ? obj.maxBinding : obj.minBinding;
  if (!binding || !binding.enabled) return fixed;
  const connectionId = String(binding.connection_id || "");
  const tagName = String(binding.tag || "");
  if (!connectionId || !tagName) return fixed;
  const raw = tagValueCache.get(normalizeTagCacheKey(connectionId, tagName));
  const numeric = coerceTagNumber(raw);
  return numeric === null ? fixed : numeric;
};

const appendBarTicks = (parent, x, y, w, h, orientation, tickConfig, colorFallback) => {
  if (!parent) return;
  if (!tickConfig?.enabled) return;
  const ns = "http://www.w3.org/2000/svg";
  const majorCount = Math.max(2, Math.trunc(Number(tickConfig.major ?? 5)) || 5);
  const minorCount = Math.max(0, Math.trunc(Number(tickConfig.minor ?? 4)) || 0);
  const stroke = tickConfig.color || colorFallback || "#ffffff";
  const strokeWidth = Math.max(0, Number(tickConfig.width ?? 2));
  if (!strokeWidth) return;
  const majorLen = 14;
  const minorLen = 10;
  const pad = 2;

  const addTick = (x1, y1, x2, y2) => {
    const tick = document.createElementNS(ns, "line");
    tick.setAttribute("x1", x1);
    tick.setAttribute("y1", y1);
    tick.setAttribute("x2", x2);
    tick.setAttribute("y2", y2);
    tick.setAttribute("stroke", stroke);
    tick.setAttribute("stroke-width", strokeWidth);
    tick.setAttribute("stroke-opacity", "0.9");
    tick.setAttribute("stroke-linecap", "round");
    tick.setAttribute("vector-effect", "non-scaling-stroke");
    parent.appendChild(tick);
  };

  for (let i = 0; i < majorCount; i += 1) {
    const t = majorCount === 1 ? 0 : i / (majorCount - 1);
    if (orientation === "horizontal") {
      const px = x + w * t;
      addTick(px, y + h - pad, px, y + h - pad - majorLen);
      if (i < majorCount - 1 && minorCount > 0) {
        for (let m = 1; m <= minorCount; m += 1) {
          const mt = (i + m / (minorCount + 1)) / (majorCount - 1);
          const mx = x + w * mt;
          addTick(mx, y + h - pad, mx, y + h - pad - minorLen);
        }
      }
    } else {
      const py = y + h * (1 - t);
      addTick(x + pad, py, x + pad + majorLen, py);
      if (i < majorCount - 1 && minorCount > 0) {
        for (let m = 1; m <= minorCount; m += 1) {
          const mt = (i + m / (minorCount + 1)) / (majorCount - 1);
          const my = y + h * (1 - mt);
          addTick(x + pad, my, x + pad + minorLen, my);
        }
      }
    }
  }
};

const shouldRenderObject = (obj) => {
  if (!obj) return false;
  if (isEditMode) return true;
  const vis = obj.visibility;
  if (!vis || vis.enabled === false) return true;
  if (vis.sourceType === "expression") {
    const result = evaluateVisibilityExpression(vis.expression);
    if (result === null || result === undefined) return true;
    const isOn = coerceTagBoolean(result);
    return vis.invert ? !isOn : isOn;
  }
  const connectionId = String(vis.connection_id || "");
  const tag = String(vis.tag || "");
  if (!connectionId || !tag) return true;
  const key = normalizeTagCacheKey(connectionId, tag);
  const value = key ? tagValueCache.get(key) : undefined;
  if (value === undefined || value === null) return true;
  const thresholdRaw = (vis.threshold !== undefined && vis.threshold !== null && vis.threshold !== "")
    ? vis.threshold
    : vis.value; // legacy alias
  const hasThreshold = thresholdRaw !== undefined && thresholdRaw !== null && thresholdRaw !== "";
  const hasMatch = String(vis.match ?? "").trim() !== "";
  const mode = (vis.mode === "equals" || vis.mode === "threshold") ? vis.mode : "";
  const hasExplicit = hasThreshold || hasMatch || mode;
  if (hasExplicit) {
    const config = {
      ...vis,
      enabled: true,
      threshold: hasThreshold ? thresholdRaw : vis.threshold
    };
    const state = getAutomationState(value, config);
    if (state === null) return true;
    return state;
  }
  const isOn = coerceTagBoolean(value);
  return vis.invert ? !isOn : isOn;
};

const getAutomationState = (value, config) => {
  if (!config || !config.enabled) return null;

  const mode = (config.mode === "equals" || config.mode === "threshold") ? config.mode : "threshold";
  if (mode === "equals") {
    const matchRaw = String(config.match ?? "").trim();
    if (!matchRaw) return null;
    if (value === undefined || value === null) return null;

    const numericMatch = Number(matchRaw);
    const numericValue = coerceTagNumber(value);
    if (Number.isFinite(numericMatch) && numericValue !== null) {
      const isOn = numericValue === numericMatch;
      return config.invert ? !isOn : isOn;
    }

    const normalizedMatch = matchRaw.toLowerCase();
    const isBoolMatch = ["true", "false", "on", "off", "yes", "no"].includes(normalizedMatch);
    if (isBoolMatch) {
      const isOn = coerceTagBoolean(value) === coerceTagBoolean(matchRaw);
      return config.invert ? !isOn : isOn;
    }

    const isOn = String(value).trim() === matchRaw;
    return config.invert ? !isOn : isOn;
  }

  const hasThreshold = config.threshold !== undefined && config.threshold !== null && config.threshold !== "";
  if (hasThreshold) {
    const thresholdValue = Number(config.threshold);
    if (!Number.isFinite(thresholdValue)) return null;
    const numeric = coerceTagNumber(value);
    if (numeric === null) return null;
    const isOn = numeric >= thresholdValue;
    return config.invert ? !isOn : isOn;
  }

  const isOn = coerceTagBoolean(value);
  return config.invert ? !isOn : isOn;
};

const getColorRuleFlashTag = (rule) => (
  rule?.flashRate === "fast"
    ? "System/Clock/FastBlink"
    : "System/Clock/SlowBlink"
);

const isColorRuleFlashActive = (rule) => {
  if (!rule?.flashEnabled) return true;
  const key = normalizeTagCacheKey("_system", getColorRuleFlashTag(rule));
  const rawValue = tagValueCache.get(key);
  if (rawValue === undefined || rawValue === null) return false;
  const state = coerceTagBoolean(rawValue);
  const expected = rule.flashWhen === false ? false : true;
  return state === expected;
};

const getAutomationColor = (config, baseColor) => {
  if (!config || isEditMode) return baseColor;
  const rules = getColorAutomationRules(config);
  if (!rules.length) return baseColor;
  for (const rule of rules) {
    if (!rule || !rule.enabled) continue;
    if (rule.sourceType === "expression") {
      const result = evaluateAutomationExpression(rule.expression);
      if (result === null || result === undefined) continue;
      const isOn = rule.invert ? !coerceTagBoolean(result) : coerceTagBoolean(result);
      if (isOn && isColorRuleFlashActive(rule)) return rule.onColor || baseColor;
      continue;
    }
    const connectionId = String(rule.connection_id || "");
    const tag = String(rule.tag || "");
    if (!connectionId || !tag) continue;
    const rawValue = tagValueCache.get(normalizeTagCacheKey(connectionId, tag));
    const state = getAutomationState(rawValue, rule);
    if (state && isColorRuleFlashActive(rule)) return rule.onColor || baseColor;
  }
  return baseColor;
};

const getActiveAutomationOverrideColor = (config) => {
  if (!config || isEditMode) return null;
  const rules = getColorAutomationRules(config);
  for (const rule of rules) {
    if (!rule || !rule.enabled) continue;
    const onColor = String(rule.onColor || "").trim();
    if (!onColor) continue;
    if (rule.sourceType === "expression") {
      const result = evaluateAutomationExpression(rule.expression);
      if (result === null || result === undefined) continue;
      const isOn = rule.invert ? !coerceTagBoolean(result) : coerceTagBoolean(result);
      if (isOn && isColorRuleFlashActive(rule)) return onColor;
      continue;
    }
    const connectionId = String(rule.connection_id || "");
    const tag = String(rule.tag || "");
    if (!connectionId || !tag) continue;
    const rawValue = tagValueCache.get(normalizeTagCacheKey(connectionId, tag));
    const state = getAutomationState(rawValue, rule);
    if (state && isColorRuleFlashActive(rule)) return onColor;
  }
  return null;
};

const getGroupColorOverrides = (groupObj) => {
  if (!groupObj || groupObj.type !== "group") return null;
  const overrides = {};
  const stateOverrides = getMultiStateVisualOverrides(groupObj);
  const fillColor = getActiveAutomationOverrideColor(groupObj.fillAutomation);
  const lineColor = getActiveAutomationOverrideColor(groupObj.strokeAutomation);
  const textColor = getActiveAutomationOverrideColor(groupObj.textColorAutomation);
  const backgroundColor = getActiveAutomationOverrideColor(groupObj.backgroundAutomation);
  const borderColor = getActiveAutomationOverrideColor(groupObj.borderColorAutomation);
  if (stateOverrides?.fillColor) overrides.fillColor = stateOverrides.fillColor;
  else if (fillColor) overrides.fillColor = fillColor;
  if (lineColor) overrides.lineColor = lineColor;
  if (textColor) overrides.textColor = textColor;
  if (stateOverrides?.backgroundColor) overrides.backgroundColor = stateOverrides.backgroundColor;
  else if (backgroundColor) overrides.backgroundColor = backgroundColor;
  if (stateOverrides?.borderColor) overrides.borderColor = stateOverrides.borderColor;
  else if (borderColor) overrides.borderColor = borderColor;
  return Object.keys(overrides).length ? overrides : null;
};

const mergeGroupColorOverrides = (parentOverrides, localOverrides) => {
  if (!parentOverrides && !localOverrides) return null;
  return { ...(parentOverrides || {}), ...(localOverrides || {}) };
};

const applyGroupColorOverridesToObject = (sourceObj, overrides) => {
  if (!sourceObj || !overrides || !Object.keys(overrides).length) return sourceObj;
  const obj = { ...sourceObj };
  const hasStrokeProp = Object.prototype.hasOwnProperty.call(obj, "stroke");
  const type = String(obj.type || "").trim();

  if (overrides.fillColor) {
    if (["rect", "alarms-panel", "ellipse", "circle", "polygon", "bar", "button", "indicator"].includes(type)) {
      obj.fill = overrides.fillColor;
      delete obj.fillAutomation;
    } else if (type === "text") {
      obj.fill = overrides.fillColor;
      delete obj.fillAutomation;
    } else if (["number-input"].includes(type)) {
      obj.textColor = overrides.fillColor;
      delete obj.textColorAutomation;
    }
  }
  if (overrides.lineColor) {
    if (["rect", "alarms-panel", "ellipse", "circle", "line", "curve", "polyline", "spline", "polygon", "button", "indicator"].includes(type) || hasStrokeProp) {
      obj.stroke = overrides.lineColor;
      delete obj.strokeAutomation;
    }
  }
  if (overrides.textColor) {
    if (type === "text") {
      obj.fill = overrides.textColor;
      delete obj.fillAutomation;
    } else if (["button", "indicator", "number-input"].includes(type)) {
      obj.textColor = overrides.textColor;
      delete obj.textColorAutomation;
    }
  }
  if (overrides.backgroundColor && type === "text") {
    obj.background = overrides.backgroundColor;
    delete obj.backgroundAutomation;
  }
  if (overrides.borderColor && type === "text") {
    obj.borderColor = overrides.borderColor;
    delete obj.borderColorAutomation;
  }
  return obj;
};

const getAutomationText = (config, baseText, bindings = {}, previewOnly = false) => {
  if (!config || !config.enabled || isEditMode) return renderBoundTemplate(baseText, bindings, previewOnly);
  const connectionId = String(config.connection_id || "");
  const tag = String(config.tag || "");
  if (!connectionId || !tag) return renderBoundTemplate(baseText, bindings, previewOnly);
  const rawValue = tagValueCache.get(normalizeTagCacheKey(connectionId, tag));
  const state = getAutomationState(rawValue, config);
  if (state === null) return renderBoundTemplate(baseText, bindings, previewOnly);
  const nextText = state ? (config.onText || baseText) : (config.offText || baseText);
  return renderBoundTemplate(nextText, bindings, previewOnly);
};

const ROTATION_PIVOT_TYPES = new Set(["text", "button", "viewport", "rect", "ellipse", "alarms-panel", "bar", "number-input", "indicator", "image", "group", "line"]);
const MOTION_POSE_TYPES = new Set(["text", "button", "viewport", "rect", "ellipse", "alarms-panel", "bar", "number-input", "indicator", "image", "group", "line", "circle"]);

const getObjectRotationFrame = (obj, boundsOverride = null) => {
  if (!obj) return null;
  if (obj.type === "line") {
    const x1 = Number(obj.x1 ?? 0);
    const y1 = Number(obj.y1 ?? 0);
    const x2 = Number(obj.x2 ?? 0);
    const y2 = Number(obj.y2 ?? 0);
    const x = Math.min(x1, x2);
    const y = Math.min(y1, y2);
    const w = Math.abs(x2 - x1);
    const h = Math.abs(y2 - y1);
    return { x, y, w, h };
  }
  if (obj.type === "text") {
    const bounds = boundsOverride || getObjectBounds(obj);
    if (!bounds) return null;
    return {
      x: Number(bounds.x ?? 0),
      y: Number(bounds.y ?? 0),
      w: Number(bounds.width ?? 0),
      h: Number(bounds.height ?? 0)
    };
  }
  if (!ROTATION_PIVOT_TYPES.has(String(obj.type || ""))) return null;
  const bounds = boundsOverride || getObjectBounds(obj) || null;
  const x = Number(obj.x ?? bounds?.x ?? 0);
  const y = Number(obj.y ?? bounds?.y ?? 0);
  const fallbackW = obj.type === "indicator" ? 160 : 0;
  const fallbackH = obj.type === "indicator" ? 64 : 0;
  const w = Number(obj.w ?? bounds?.width ?? fallbackW);
  const h = Number(obj.h ?? bounds?.height ?? fallbackH);
  return { x, y, w, h };
};

const normalizePivotMode = (value, objectType = "") => {
  const raw = String(value || "").trim().toLowerCase();
  if (objectType === "line") {
    const allowed = new Set(["start", "center", "end", "custom"]);
    return allowed.has(raw) ? raw : "center";
  }
  const allowed = new Set(["center", "top-left", "top-center", "top-right", "middle-left", "middle-right", "bottom-left", "bottom-center", "bottom-right", "custom"]);
  return allowed.has(raw) ? raw : "center";
};

const resolvePivotLocal = (obj, frame) => {
  const w = Math.max(0, Number(frame?.w ?? 0));
  const h = Math.max(0, Number(frame?.h ?? 0));
  const type = String(obj?.type || "");
  const mode = normalizePivotMode(obj?.pivotMode, type);
  if (type === "line") {
    const frameX = Number(frame?.x ?? 0);
    const frameY = Number(frame?.y ?? 0);
    const startLocal = {
      x: Number(obj?.x1 ?? 0) - frameX,
      y: Number(obj?.y1 ?? 0) - frameY
    };
    const endLocal = {
      x: Number(obj?.x2 ?? 0) - frameX,
      y: Number(obj?.y2 ?? 0) - frameY
    };
    if (mode === "custom") {
      const fallbackX = (startLocal.x + endLocal.x) / 2;
      const fallbackY = (startLocal.y + endLocal.y) / 2;
      return {
        mode,
        x: Number.isFinite(Number(obj?.pivotX)) ? Number(obj.pivotX) : fallbackX,
        y: Number.isFinite(Number(obj?.pivotY)) ? Number(obj.pivotY) : fallbackY
      };
    }
    if (mode === "start") return { mode, ...startLocal };
    if (mode === "end") return { mode, ...endLocal };
    return {
      mode: "center",
      x: (startLocal.x + endLocal.x) / 2,
      y: (startLocal.y + endLocal.y) / 2
    };
  }
  if (mode === "custom") {
    const fallbackX = w / 2;
    const fallbackY = h / 2;
    return {
      mode,
      x: Number.isFinite(Number(obj?.pivotX)) ? Number(obj.pivotX) : fallbackX,
      y: Number.isFinite(Number(obj?.pivotY)) ? Number(obj.pivotY) : fallbackY
    };
  }
  const map = {
    center: { x: w / 2, y: h / 2 },
    "top-left": { x: 0, y: 0 },
    "top-center": { x: w / 2, y: 0 },
    "top-right": { x: w, y: 0 },
    "middle-left": { x: 0, y: h / 2 },
    "middle-right": { x: w, y: h / 2 },
    "bottom-left": { x: 0, y: h },
    "bottom-center": { x: w / 2, y: h },
    "bottom-right": { x: w, y: h }
  };
  return { mode, ...(map[mode] || map.center) };
};

const getRotationPivot = (obj, boundsOverride = null, offset = { x: 0, y: 0 }) => {
  const frame = getObjectRotationFrame(obj, boundsOverride);
  if (!frame) return null;
  const local = resolvePivotLocal(obj, frame);
  return {
    frame,
    localX: Number(local.x ?? 0),
    localY: Number(local.y ?? 0),
    worldX: Number(frame.x ?? 0) + Number(offset?.x ?? 0) + Number(local.x ?? 0),
    worldY: Number(frame.y ?? 0) + Number(offset?.y ?? 0) + Number(local.y ?? 0),
    mode: local.mode
  };
};

const getRotationAutomationValue = (obj) => {
  if (!obj || isEditMode) return 0;
  const automation = normalizeRotationAutomationState(obj.rotationAutomation);
  if (!automation || automation.enabled === false) return 0;
  let numeric = null;
  if (automation.sourceType === "expression") {
    numeric = coerceTagNumber(evaluateAutomationExpression(automation.expression));
  } else {
    const connectionId = String(automation.connection_id || "").trim();
    const tag = String(automation.tag || "").trim();
    if (!connectionId || !tag) return 0;
    const raw = tagValueCache.get(normalizeTagCacheKey(connectionId, tag));
    numeric = coerceTagNumber(raw);
  }
  if (numeric === null) return 0;
  const inputMin = Number.isFinite(Number(automation.inputMin)) ? Number(automation.inputMin) : 0;
  const inputMax = Number.isFinite(Number(automation.inputMax)) ? Number(automation.inputMax) : 1;
  const angleStart = Number.isFinite(Number(automation.angleStart)) ? Number(automation.angleStart) : 0;
  const angleEnd = Number.isFinite(Number(automation.angleEnd)) ? Number(automation.angleEnd) : 0;
  const direction = String(automation.direction || "shortest").trim().toLowerCase();
  let t = 0;
  if (inputMax === inputMin) {
    t = numeric >= inputMax ? 1 : 0;
  } else {
    t = Math.max(0, Math.min(1, (numeric - inputMin) / (inputMax - inputMin)));
  }
  let delta = angleEnd - angleStart;
  if (direction === "cw") {
    delta = ((angleEnd - angleStart) % 360 + 360) % 360;
  } else if (direction === "ccw") {
    delta = -(((angleStart - angleEnd) % 360 + 360) % 360);
  } else {
    delta = ((angleEnd - angleStart + 540) % 360) - 180;
  }
  return angleStart + (delta * t);
};

const getObjectRotationDegrees = (obj) => {
  const multiStateRotation = getMultiStateRotationOverride(obj);
  if (multiStateRotation !== null) return multiStateRotation;
  const base = Number.isFinite(Number(obj?.rotation)) ? Number(obj.rotation) : 0;
  return base + getRotationAutomationValue(obj);
};

const supportsMotionPose = (obj) => Boolean(obj && MOTION_POSE_TYPES.has(String(obj.type || "")));

const captureMotionPose = (obj) => {
  if (!supportsMotionPose(obj)) return null;
  if (obj.type === "line") {
    return {
      x1: Number(obj.x1 ?? 0),
      y1: Number(obj.y1 ?? 0),
      x2: Number(obj.x2 ?? 0),
      y2: Number(obj.y2 ?? 0)
    };
  }
  if (obj.type === "circle") {
    return {
      cx: Number(obj.cx ?? 0),
      cy: Number(obj.cy ?? 0),
      r: Number(obj.r ?? 0)
    };
  }
  return {
    x: Number(obj.x ?? 0),
    y: Number(obj.y ?? 0),
    w: Number(obj.w ?? 0),
    h: Number(obj.h ?? 0),
    rotation: Number(obj.rotation ?? 0)
  };
};

const applyMotionPoseToObject = (obj, pose) => {
  if (!obj || !pose) return;
  if (obj.type === "line") {
    obj.x1 = Number(pose.x1 ?? obj.x1 ?? 0);
    obj.y1 = Number(pose.y1 ?? obj.y1 ?? 0);
    obj.x2 = Number(pose.x2 ?? obj.x2 ?? 0);
    obj.y2 = Number(pose.y2 ?? obj.y2 ?? 0);
    return;
  }
  if (obj.type === "circle") {
    obj.cx = Number(pose.cx ?? obj.cx ?? 0);
    obj.cy = Number(pose.cy ?? obj.cy ?? 0);
    if ("r" in pose) obj.r = Number(pose.r ?? obj.r ?? 0);
    return;
  }
  if ("x" in pose) obj.x = Number(pose.x ?? obj.x ?? 0);
  if ("y" in pose) obj.y = Number(pose.y ?? obj.y ?? 0);
  if ("w" in pose) obj.w = Number(pose.w ?? obj.w ?? 0);
  if ("h" in pose) obj.h = Number(pose.h ?? obj.h ?? 0);
  if ("rotation" in pose) obj.rotation = Number(pose.rotation ?? obj.rotation ?? 0);
};

const interpolateMotionPose = (obj, startPose, endPose, t) => {
  if (!obj || !startPose || !endPose) return null;
  const amount = Math.max(0, Math.min(1, Number(t ?? 0)));
  if (obj.type === "line") {
    return {
      x1: Number(startPose.x1 ?? 0) + (Number(endPose.x1 ?? 0) - Number(startPose.x1 ?? 0)) * amount,
      y1: Number(startPose.y1 ?? 0) + (Number(endPose.y1 ?? 0) - Number(startPose.y1 ?? 0)) * amount,
      x2: Number(startPose.x2 ?? 0) + (Number(endPose.x2 ?? 0) - Number(startPose.x2 ?? 0)) * amount,
      y2: Number(startPose.y2 ?? 0) + (Number(endPose.y2 ?? 0) - Number(startPose.y2 ?? 0)) * amount
    };
  }
  if (obj.type === "circle") {
    return {
      cx: Number(startPose.cx ?? 0) + (Number(endPose.cx ?? 0) - Number(startPose.cx ?? 0)) * amount,
      cy: Number(startPose.cy ?? 0) + (Number(endPose.cy ?? 0) - Number(startPose.cy ?? 0)) * amount,
      r: Number(startPose.r ?? 0) + (Number(endPose.r ?? 0) - Number(startPose.r ?? 0)) * amount
    };
  }
  return {
    x: Number(startPose.x ?? 0) + (Number(endPose.x ?? 0) - Number(startPose.x ?? 0)) * amount,
    y: Number(startPose.y ?? 0) + (Number(endPose.y ?? 0) - Number(startPose.y ?? 0)) * amount,
    w: Number(startPose.w ?? 0) + (Number(endPose.w ?? 0) - Number(startPose.w ?? 0)) * amount,
    h: Number(startPose.h ?? 0) + (Number(endPose.h ?? 0) - Number(startPose.h ?? 0)) * amount,
    rotation: Number(startPose.rotation ?? 0) + (Number(endPose.rotation ?? 0) - Number(startPose.rotation ?? 0)) * amount
  };
};

const getMotionPreviewT = (obj) => {
  if (!isEditMode || selectedIndices.length !== 1 || !obj) return null;
  const activeObjects = getActiveObjects();
  const selectedObj = activeObjects?.[selectedIndices[0]] || null;
  if (obj !== selectedObj) return null;
  for (const control of motionControlConfigs) {
    if (control.types.includes(obj.type)) {
      const preview = Number(control.previewInput?.value ?? 0);
      return Number.isFinite(preview) ? Math.max(0, Math.min(1, preview / 100)) : 0;
    }
  }
  return null;
};

const getMotionTFromSource = (motion) => {
  const normalized = normalizeMotionAutomationState(motion);
  if (!normalized || normalized.enabled === false) return null;
  let numeric = null;
  if (normalized.sourceType === "expression") {
    numeric = coerceTagNumber(evaluateAutomationExpression(normalized.expression));
  } else {
    const connectionId = String(normalized.connection_id || "").trim();
    const tag = String(normalized.tag || "").trim();
    if (!connectionId || !tag) return null;
    const raw = tagValueCache.get(normalizeTagCacheKey(connectionId, tag));
    numeric = coerceTagNumber(raw);
  }
  if (numeric === null) return null;
  const inputMin = Number.isFinite(Number(normalized.inputMin)) ? Number(normalized.inputMin) : 0;
  const inputMax = Number.isFinite(Number(normalized.inputMax)) ? Number(normalized.inputMax) : 1;
  if (inputMax === inputMin) return numeric >= inputMax ? 1 : 0;
  return Math.max(0, Math.min(1, (numeric - inputMin) / (inputMax - inputMin)));
};

const getRenderedMotionObject = (sourceObj) => {
  if (!sourceObj || !supportsMotionPose(sourceObj)) return sourceObj;
  if (poseEditSession && poseEditSession.object === sourceObj) return sourceObj;
  const motion = sourceObj.motion;
  if (!motion || !motion.startPose || !motion.endPose) return sourceObj;
  const previewT = getMotionPreviewT(sourceObj);
  const t = previewT != null ? previewT : (!isEditMode ? getMotionTFromSource(motion) : null);
  if (t == null) return sourceObj;
  const pose = interpolateMotionPose(sourceObj, motion.startPose, motion.endPose, t);
  if (!pose) return sourceObj;
  const nextObj = { ...sourceObj };
  applyMotionPoseToObject(nextObj, pose);
  return nextObj;
};

const getDisplayObject = (obj) => applyMultiStateVisualOverridesToObject(getRenderedMotionObject(obj));

const applyRotationTransform = (el, obj, boundsOverride = null, offset = { x: 0, y: 0 }, rotationOverride = null) => {
  if (!el || !obj) return false;
  const rotation = rotationOverride == null ? getObjectRotationDegrees(obj) : Number(rotationOverride);
  if (!Number.isFinite(rotation) || rotation === 0) return false;
  const pivot = getRotationPivot(obj, boundsOverride, offset);
  if (!pivot) return false;
  el.setAttribute("transform", `rotate(${rotation} ${pivot.worldX} ${pivot.worldY})`);
  return true;
};

const getObjectBounds = (obj) => {
  if (!obj) return null;
  if (obj.type === "group") {
    const base = {
      x: Number(obj.x ?? 0),
      y: Number(obj.y ?? 0),
      width: Number(obj.w ?? 0),
      height: Number(obj.h ?? 0)
    };
    if (!Array.isArray(obj.children) || !obj.children.length) return base;
    const content = getGroupContentBounds(obj);
    if (!content) return base;
    const contentBox = {
      x: Number(obj.x ?? 0) + Number(content.x ?? 0),
      y: Number(obj.y ?? 0) + Number(content.y ?? 0),
      width: Number(content.width ?? 0),
      height: Number(content.height ?? 0)
    };
    const left = Math.min(base.x, contentBox.x);
    const top = Math.min(base.y, contentBox.y);
    const right = Math.max(base.x + base.width, contentBox.x + contentBox.width);
    const bottom = Math.max(base.y + base.height, contentBox.y + contentBox.height);
    return { x: left, y: top, width: right - left, height: bottom - top };
  }
  if (obj.type === "rect" || obj.type === "ellipse" || obj.type === "alarms-panel" || obj.type === "button" || obj.type === "viewport" || obj.type === "bar" || obj.type === "number-input" || obj.type === "indicator" || obj.type === "image") {
    return {
      x: Number(obj.x ?? 0),
      y: Number(obj.y ?? 0),
      width: Number(obj.w ?? 0),
      height: Number(obj.h ?? 0)
    };
  }
  if (obj.type === "circle") {
    const r = Number(obj.r ?? 0);
    const cx = Number(obj.cx ?? 0);
    const cy = Number(obj.cy ?? 0);
    return { x: cx - r, y: cy - r, width: r * 2, height: r * 2 };
  }
  if (obj.type === "line") {
    const x1 = Number(obj.x1 ?? 0);
    const y1 = Number(obj.y1 ?? 0);
    const x2 = Number(obj.x2 ?? 0);
    const y2 = Number(obj.y2 ?? 0);
    const minX = Math.min(x1, x2);
    const minY = Math.min(y1, y2);
    return { x: minX, y: minY, width: Math.abs(x2 - x1), height: Math.abs(y2 - y1) };
  }
	  if (obj.type === "curve") {
    const x1 = Number(obj.x1 ?? 0);
    const y1 = Number(obj.y1 ?? 0);
    const x2 = Number(obj.x2 ?? 0);
    const y2 = Number(obj.y2 ?? 0);
    const cx = Number(obj.cx ?? ((x1 + x2) / 2));
    const cy = Number(obj.cy ?? ((y1 + y2) / 2));
    const bx = getQuadraticBounds(x1, cx, x2);
    const by = getQuadraticBounds(y1, cy, y2);
    const strokeWidth = Math.max(0, Number(obj.strokeWidth ?? 2));
    const pad = strokeWidth / 2;
    return { x: bx.min - pad, y: by.min - pad, width: (bx.max - bx.min) + pad * 2, height: (by.max - by.min) + pad * 2 };
  }
  if (obj.type === "polyline" || obj.type === "polygon" || obj.type === "spline") {
    const points = obj.type === "spline" ? getSplineSamplePoints(obj.points) : (Array.isArray(obj.points) ? obj.points : []);
    if (!points.length) return { x: 0, y: 0, width: 0, height: 0 };
    const xs = points.map((p) => Number(p?.x ?? 0));
    const ys = points.map((p) => Number(p?.y ?? 0));
    const minX = Math.min(...xs);
    const maxX = Math.max(...xs);
    const minY = Math.min(...ys);
    const maxY = Math.max(...ys);
    const strokeWidth = Math.max(0, Number(obj.strokeWidth ?? (obj.type === "spline" ? 2 : 1)));
    const pad = strokeWidth / 2;
    return { x: minX - pad, y: minY - pad, width: (maxX - minX) + pad * 2, height: (maxY - minY) + pad * 2 };
  }
  if (obj.type === "text") {
    const x = Number(obj.x ?? 0);
    const y = Number(obj.y ?? 0);
    const fontSize = Number(obj.fontSize || 18);
    const sample = decodeNbspEntities(renderTextTemplate(obj, true));
    const measured = measureTextBlock(sample, fontSize, Boolean(obj.bold));
    if (!isTextAutoSize(obj)) {
      const fixed = getTextFixedSize(obj);
      return { x, y, width: fixed.w, height: fixed.h };
    }
    const contentW = measured.width;
    const contentH = measured.height;
    const align = obj.align || "left";
    const valign = obj.valign || "top";
    const padding = getTextBoxPadding(obj);
    const padX = padding.x;
    const padY = padding.y;
    let rectX = x - padX;
    if (align === "center") rectX = x - contentW / 2 - padX;
    if (align === "right") rectX = x - contentW - padX;
    const isMultiline = measured.lines?.length > 1;
    let rectY = y - padY;
    if (isMultiline) {
      if (valign === "middle") rectY = y - contentH / 2 - padY;
      if (valign === "bottom") rectY = y - contentH - padY;
    } else {
      if (valign === "top") rectY = (y - (measured.ascent ?? fontSize * 0.8)) - padY;
      if (valign === "middle") rectY = y - contentH / 2 - padY;
      if (valign === "bottom") rectY = y - contentH - padY;
    }
    return { x: rectX, y: rectY, width: contentW + padX * 2, height: contentH + padY * 2 };
  }
  return null;
};

const getGroupContentBounds = (groupObj) => {
  if (!groupObj || !Array.isArray(groupObj.children)) return null;
  const childBounds = groupObj.children.map(getObjectBounds).filter(Boolean);
  if (!childBounds.length) return null;
  const left = Math.min(...childBounds.map((b) => b.x));
  const top = Math.min(...childBounds.map((b) => b.y));
  const right = Math.max(...childBounds.map((b) => b.x + b.width));
  const bottom = Math.max(...childBounds.map((b) => b.y + b.height));
  return { x: left, y: top, width: right - left, height: bottom - top };
};

const getTextVisualAlignmentBounds = (obj) => {
  if (!obj || obj.type !== "text" || !isTextAutoSize(obj)) return null;
  if (paintValueCreatesBox(obj.background) || textBorderValueCreatesBox(obj)) return null;
  const x = Number(obj.x ?? 0);
  const y = Number(obj.y ?? 0);
  const fontSize = Number(obj.fontSize || 18);
  const sample = decodeNbspEntities(renderTextTemplate(obj, true));
  const ctx = getTextMeasureCtx();
  ctx.font = `${obj.bold ? "700 " : ""}${fontSize}px Arial, sans-serif`;
  const lines = splitMultiline(sample);
  const metrics = lines.map((line) => ctx.measureText(line || " "));
  if (!metrics.length) return null;
  const measured = measureTextBlock(sample, fontSize, Boolean(obj.bold));
  const align = obj.align || "left";
  const valign = obj.valign || "top";
  const lineBounds = metrics.map((metric) => {
    const width = Number(metric.width) || 0;
    const actualLeft = Number.isFinite(metric.actualBoundingBoxLeft) ? Number(metric.actualBoundingBoxLeft) : 0;
    const actualRight = Number.isFinite(metric.actualBoundingBoxRight) ? Number(metric.actualBoundingBoxRight) : width;
    let lineStart = 0;
    if (align === "center") lineStart = -width / 2;
    if (align === "right") lineStart = -width;
    return {
      left: x + lineStart - actualLeft,
      right: x + lineStart + actualRight
    };
  });
  const left = Math.min(...lineBounds.map((bounds) => bounds.left));
  const right = Math.max(...lineBounds.map((bounds) => bounds.right));
  let blockTop = y;
  if (measured.lines.length > 1) {
    if (valign === "middle") blockTop = y - measured.height / 2;
    if (valign === "bottom") blockTop = y - measured.height;
  } else {
    if (valign === "top") blockTop = y - (measured.ascent ?? fontSize * 0.8);
    if (valign === "middle") blockTop = y - measured.height / 2;
    if (valign === "bottom") blockTop = y - measured.height;
  }
  return { x: left, y: blockTop, width: right - left, height: measured.height };
};

const getObjectAlignmentBounds = (obj) => getTextVisualAlignmentBounds(obj) || getObjectBounds(obj);

const buildGroupEditMeta = () => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  const offset = getActiveOffset();
  renderedElementMeta = activeObjects
    .map((obj, index) => {
      const bounds = getObjectBounds(obj);
      if (!bounds) return null;
      return {
        index,
        type: obj.type,
        bounds: {
          x: bounds.x + offset.x,
          y: bounds.y + offset.y,
          width: bounds.width,
          height: bounds.height
        }
      };
    })
    .filter(Boolean);
};

const translateObject = (obj, dx, dy) => {
  if (!obj) return;
  if (obj.type === "line") {
    obj.x1 = Number(obj.x1 ?? 0) + dx;
    obj.y1 = Number(obj.y1 ?? 0) + dy;
    obj.x2 = Number(obj.x2 ?? 0) + dx;
    obj.y2 = Number(obj.y2 ?? 0) + dy;
    return;
  }
  if (obj.type === "curve") {
    obj.x1 = Number(obj.x1 ?? 0) + dx;
    obj.y1 = Number(obj.y1 ?? 0) + dy;
    obj.cx = Number(obj.cx ?? 0) + dx;
    obj.cy = Number(obj.cy ?? 0) + dy;
    obj.x2 = Number(obj.x2 ?? 0) + dx;
    obj.y2 = Number(obj.y2 ?? 0) + dy;
    return;
  }
  if (obj.type === "circle") {
    obj.cx = Number(obj.cx ?? 0) + dx;
    obj.cy = Number(obj.cy ?? 0) + dy;
    return;
  }
  if (obj.type === "text") {
    obj.x = Number(obj.x ?? 0) + dx;
    obj.y = Number(obj.y ?? 0) + dy;
    return;
  }
  if (obj.type === "polyline" || obj.type === "polygon" || obj.type === "spline") {
    if (!Array.isArray(obj.points)) return;
    obj.points = obj.points.map((pt) => ({
      x: Number(pt?.x ?? 0) + dx,
      y: Number(pt?.y ?? 0) + dy
    }));
    return;
  }
  if (obj.x != null) obj.x = Number(obj.x ?? 0) + dx;
  if (obj.y != null) obj.y = Number(obj.y ?? 0) + dy;
};

const canSizeMatchObject = (obj) => {
  if (!obj) return false;
  if (obj.type === "button" || obj.type === "viewport" || obj.type === "rect" || obj.type === "ellipse" || obj.type === "alarms-panel" || obj.type === "bar" || obj.type === "text" || obj.type === "number-input" || obj.type === "indicator" || obj.type === "image") return true;
  if (obj.type === "circle") return true;
  return false;
};

const applySizeToObject = (obj, refSize, mode) => {
  if (!obj || !refSize) return;
  const width = Math.max(1, Math.round(Number(refSize.width ?? 0)));
  const height = Math.max(1, Math.round(Number(refSize.height ?? 0)));
  if (obj.type === "circle") {
    const diameter = Math.max(1, Math.round(Math.min(width, height)));
    obj.r = Math.max(1, Math.round(diameter / 2));
    return;
  }
  if (obj.type === "text") {
    obj.autoSize = false;
    if (mode === "width" || mode === "size") obj.w = width;
    if (mode === "height" || mode === "size") obj.h = height;
    return;
  }
  if (obj.type === "button" || obj.type === "viewport" || obj.type === "rect" || obj.type === "ellipse" || obj.type === "alarms-panel" || obj.type === "bar" || obj.type === "number-input" || obj.type === "indicator" || obj.type === "image") {
    if (mode === "width" || mode === "size") obj.w = Math.max(MIN_RESIZE_SIZE, width);
    if (mode === "height" || mode === "size") obj.h = Math.max(MIN_RESIZE_SIZE, height);
  }
};

const matchSelectedSize = (mode) => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (selectedIndices.length < 2) return;
  const targets = selectedIndices
    .map((idx) => activeObjects[idx])
    .filter((obj) => canSizeMatchObject(obj));
  if (targets.length < 2) return;
  const bounds = targets.map(getObjectBounds).filter(Boolean);
  if (!bounds.length) return;
  const targetSize = {
    width: Math.max(...bounds.map((b) => Number(b.width ?? 0))),
    height: Math.max(...bounds.map((b) => Number(b.height ?? 0)))
  };
  recordHistory();
  targets.forEach((obj) => applySizeToObject(obj, targetSize, mode));
  renderScreen();
  syncEditorFromScreen();
  updateSelectionOverlays();
  updatePropertiesPanel();
  setDirty(true);
};

const spaceSelectedEvenly = (axis) => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (selectedIndices.length < 3) return;
  const items = selectedIndices
    .map((idx) => ({ idx, obj: activeObjects[idx] }))
    .filter((item) => item.obj && canSizeMatchObject(item.obj))
    .map((item) => {
      const b = getObjectBounds(item.obj);
      if (!b) return null;
      return {
        idx: item.idx,
        obj: item.obj,
        bounds: b,
        cx: b.x + b.width / 2,
        cy: b.y + b.height / 2
      };
    })
    .filter(Boolean);
  if (items.length < 3) return;

  const sorted = [...items].sort((a, b) => (axis === "x" ? a.cx - b.cx : a.cy - b.cy));
  const start = axis === "x" ? sorted[0].cx : sorted[0].cy;
  const end = axis === "x" ? sorted[sorted.length - 1].cx : sorted[sorted.length - 1].cy;
  const span = end - start;
  if (!Number.isFinite(span) || span === 0) return;
  const step = span / (sorted.length - 1);
  recordHistory();
  sorted.forEach((item, index) => {
    const desired = start + step * index;
    const current = axis === "x" ? item.cx : item.cy;
    const delta = desired - current;
    if (axis === "x") translateObject(item.obj, delta, 0);
    else translateObject(item.obj, 0, delta);
  });
  renderScreen();
  syncEditorFromScreen();
  updateSelectionOverlays();
  updatePropertiesPanel();
  setDirty(true);
};

const alignSelected = (mode) => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (selectedIndices.length < 2) return;
  const items = selectedIndices
    .map((idx) => ({ idx, obj: activeObjects[idx] }))
    .filter((item) => item.obj)
    .map((item) => ({ ...item, bounds: getObjectAlignmentBounds(item.obj) }))
    .filter((item) => item.bounds);
  if (!items.length) return;
  const anchorItem = Number.isInteger(selectionAnchorIndex)
    ? items.find((item) => item.idx === selectionAnchorIndex)
    : null;
  if (anchorItem && items.length > 1) {
    const anchorBounds = anchorItem.bounds;
    const anchorLeft = anchorBounds.x;
    const anchorRight = anchorBounds.x + anchorBounds.width;
    const anchorTop = anchorBounds.y;
    const anchorBottom = anchorBounds.y + anchorBounds.height;
    const anchorCenterX = anchorBounds.x + anchorBounds.width / 2;
    const anchorCenterY = anchorBounds.y + anchorBounds.height / 2;
    recordHistory();
    items.forEach((item) => {
      if (item.idx === anchorItem.idx) return;
      const b = item.bounds;
      let dx = 0;
      let dy = 0;
      if (mode === "left") dx = anchorLeft - b.x;
      if (mode === "right") dx = anchorRight - (b.x + b.width);
      if (mode === "center") dx = anchorCenterX - (b.x + b.width / 2);
      if (mode === "top") dy = anchorTop - b.y;
      if (mode === "bottom") dy = anchorBottom - (b.y + b.height);
      if (mode === "middle") dy = anchorCenterY - (b.y + b.height / 2);
      translateObject(item.obj, dx, dy);
    });
    renderScreen();
    syncEditorFromScreen();
    setDirty(true);
    return;
  }
  const bounds = items.map((item) => item.bounds);
  const left = Math.min(...bounds.map((b) => b.x));
  const right = Math.max(...bounds.map((b) => b.x + b.width));
  const top = Math.min(...bounds.map((b) => b.y));
  const bottom = Math.max(...bounds.map((b) => b.y + b.height));
  const centerX = (left + right) / 2;
  const centerY = (top + bottom) / 2;

  recordHistory();
  items.forEach((item) => {
    const b = item.bounds;
    let dx = 0;
    let dy = 0;
    if (mode === "left") dx = left - b.x;
    if (mode === "right") dx = right - (b.x + b.width);
    if (mode === "center") dx = centerX - (b.x + b.width / 2);
    if (mode === "top") dy = top - b.y;
    if (mode === "bottom") dy = bottom - (b.y + b.height);
    if (mode === "middle") dy = centerY - (b.y + b.height / 2);
    translateObject(item.obj, dx, dy);
  });

  renderScreen();
  syncEditorFromScreen();
  setDirty(true);
};

const swapAlignHorizontal = (value) => {
  if (value === "left") return "right";
  if (value === "right") return "left";
  return value;
};

const swapAlignVertical = (value) => {
  if (value === "top") return "bottom";
  if (value === "bottom") return "top";
  return value;
};

const flipObjectInBox = (obj, axis, box) => {
  if (!obj || !box) return;
  const centerX = box.x + box.width / 2;
  const centerY = box.y + box.height / 2;

  const applyRotationFlip = () => {
    if (obj.rotation == null) return;
    const rotationValue = Number(obj.rotation);
    if (!Number.isFinite(rotationValue) || rotationValue === 0) return;
    obj.rotation = -rotationValue;
  };

  if (obj.type === "group") {
    const groupX = Number(obj.x ?? 0);
    const groupY = Number(obj.y ?? 0);
    const groupW = Number(obj.w ?? 0);
    const groupH = Number(obj.h ?? 0);
    if (axis === "horizontal") obj.x = Math.round(2 * centerX - (groupX + groupW));
    if (axis === "vertical") obj.y = Math.round(2 * centerY - (groupY + groupH));
    applyRotationFlip();

    const children = Array.isArray(obj.children) ? obj.children : [];
    const childBox = { x: 0, y: 0, width: groupW, height: groupH };
    children.forEach((child) => flipObjectInBox(child, axis, childBox));
    return;
  }

  if (obj.type === "line") {
    const x1 = Number(obj.x1 ?? 0);
    const x2 = Number(obj.x2 ?? 0);
    const y1 = Number(obj.y1 ?? 0);
    const y2 = Number(obj.y2 ?? 0);
    if (axis === "horizontal") {
      obj.x1 = 2 * centerX - x1;
      obj.x2 = 2 * centerX - x2;
    } else {
      obj.y1 = 2 * centerY - y1;
      obj.y2 = 2 * centerY - y2;
    }
    applyRotationFlip();
    return;
  }

  if (obj.type === "circle") {
    const cx = Number(obj.cx ?? 0);
    const cy = Number(obj.cy ?? 0);
    if (axis === "horizontal") obj.cx = 2 * centerX - cx;
    else obj.cy = 2 * centerY - cy;
    applyRotationFlip();
    return;
  }

  if (obj.type === "polyline" || obj.type === "polygon" || obj.type === "spline") {
    if (!Array.isArray(obj.points)) return;
    obj.points = obj.points.map((pt) => ({
      x: axis === "horizontal" ? 2 * centerX - Number(pt?.x ?? 0) : Number(pt?.x ?? 0),
      y: axis === "vertical" ? 2 * centerY - Number(pt?.y ?? 0) : Number(pt?.y ?? 0)
    }));
    applyRotationFlip();
    return;
  }

  if (obj.type === "text") {
    if (!isTextAutoSize(obj)) {
      const bounds = getObjectBounds(obj);
      if (!bounds) return;
      if (axis === "horizontal") obj.x = Math.round(2 * centerX - (bounds.x + bounds.width));
      else obj.y = Math.round(2 * centerY - (bounds.y + bounds.height));
      applyRotationFlip();
      return;
    }
    const x = Number(obj.x ?? 0);
    const y = Number(obj.y ?? 0);
    if (axis === "horizontal") {
      obj.x = 2 * centerX - x;
      if (obj.align) obj.align = swapAlignHorizontal(obj.align);
    } else {
      obj.y = 2 * centerY - y;
      if (obj.valign) obj.valign = swapAlignVertical(obj.valign);
    }
    applyRotationFlip();
    return;
  }

  const bounds = getObjectBounds(obj);
  if (!bounds) return;
  if (axis === "horizontal" && obj.x != null) {
    obj.x = Math.round(2 * centerX - (Number(obj.x ?? 0) + Number(bounds.width ?? 0)));
    if (obj.align) obj.align = swapAlignHorizontal(obj.align);
  }
  if (axis === "vertical" && obj.y != null) {
    obj.y = Math.round(2 * centerY - (Number(obj.y ?? 0) + Number(bounds.height ?? 0)));
    if (obj.valign) obj.valign = swapAlignVertical(obj.valign);
  }
  applyRotationFlip();
};

const flipSelected = (axis) => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (!selectedIndices.length) return;
  const bounds = getSelectionBoundsActive();
  if (!bounds) return;

  recordHistory();
  const indices = Array.from(new Set(selectedIndices))
    .filter((idx) => Number.isInteger(idx) && idx >= 0 && idx < activeObjects.length)
    .sort((a, b) => a - b);
  indices.forEach((idx) => flipObjectInBox(activeObjects[idx], axis, bounds));
  renderScreen();
  syncEditorFromScreen();
  updateSelectionOverlays();
  updatePropertiesPanel();
  setDirty(true);
};

const groupSelected = () => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (selectedIndices.length < 2) return;
  const indices = Array.from(new Set(selectedIndices)).sort((a, b) => a - b);
  const targets = indices.map((idx) => activeObjects[idx]).filter(Boolean);
  const bounds = targets.map(getObjectBounds).filter(Boolean);
  if (!bounds.length) return;
  const left = Math.min(...bounds.map((b) => b.x));
  const right = Math.max(...bounds.map((b) => b.x + b.width));
  const top = Math.min(...bounds.map((b) => b.y));
  const bottom = Math.max(...bounds.map((b) => b.y + b.height));
  const groupObj = {
    type: "group",
    x: Math.round(left),
    y: Math.round(top),
    w: Math.round(right - left),
    h: Math.round(bottom - top),
    rotation: 0,
    visibility: null,
    children: targets.map((obj) => {
      const clone = JSON.parse(JSON.stringify(obj));
      translateObject(clone, -left, -top);
      return clone;
    })
  };
  recordHistory();
  const deleteSet = new Set(indices);
  const nextObjects = activeObjects.filter((_, index) => !deleteSet.has(index));
  const insertIndex = indices[0];
  nextObjects.splice(insertIndex, 0, groupObj);
  setActiveObjects(nextObjects);
  selectedIndices = [insertIndex];
  renderScreen();
  syncEditorFromScreen();
  updateSelectionOverlays();
  updatePropertiesPanel();
  setDirty(true);
};

const ungroupSelected = () => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (!selectedIndices.length) return;
  const groupIndices = new Set(
    selectedIndices.filter((idx) => activeObjects[idx]?.type === "group")
  );
  if (!groupIndices.size) return;
  recordHistory();
  const nextObjects = [];
  const nextSelected = [];
  activeObjects.forEach((obj, index) => {
    if (!groupIndices.has(index)) {
      nextObjects.push(obj);
      return;
    }
    const offsetX = Number(obj.x ?? 0);
    const offsetY = Number(obj.y ?? 0);
    const children = Array.isArray(obj.children) ? obj.children : [];
    children.forEach((child) => {
      const clone = JSON.parse(JSON.stringify(child));
      translateObject(clone, offsetX, offsetY);
      nextObjects.push(clone);
      nextSelected.push(nextObjects.length - 1);
    });
  });
  setActiveObjects(nextObjects);
  selectedIndices = nextSelected;
  renderScreen();
  syncEditorFromScreen();
  updateSelectionOverlays();
  updatePropertiesPanel();
  refreshViewportIdOptions();
  setDirty(true);
};

const moveSelectionToFront = () => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (!selectedIndices.length) return;

  const indices = Array.from(new Set(selectedIndices))
    .filter((idx) => Number.isInteger(idx) && idx >= 0 && idx < activeObjects.length)
    .sort((a, b) => a - b);
  if (!indices.length) return;

  recordHistory();
  const selectedSet = new Set(indices);
  const selected = [];
  const unselected = [];
  activeObjects.forEach((obj, index) => {
    if (selectedSet.has(index)) selected.push(obj);
    else unselected.push(obj);
  });
  const nextObjects = unselected.concat(selected);
  setActiveObjects(nextObjects);
  selectedIndices = selected.map((_, idx) => unselected.length + idx);
  renderScreen();
  syncEditorFromScreen();
  updateSelectionOverlays();
  updatePropertiesPanel();
  setDirty(true);
};

const moveSelectionToBack = () => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (!selectedIndices.length) return;

  const indices = Array.from(new Set(selectedIndices))
    .filter((idx) => Number.isInteger(idx) && idx >= 0 && idx < activeObjects.length)
    .sort((a, b) => a - b);
  if (!indices.length) return;

  recordHistory();
  const selectedSet = new Set(indices);
  const selected = [];
  const unselected = [];
  activeObjects.forEach((obj, index) => {
    if (selectedSet.has(index)) selected.push(obj);
    else unselected.push(obj);
  });
  const nextObjects = selected.concat(unselected);
  setActiveObjects(nextObjects);
  selectedIndices = selected.map((_, idx) => idx);
  renderScreen();
  syncEditorFromScreen();
  updateSelectionOverlays();
  updatePropertiesPanel();
  setDirty(true);
};

const updateMenuState = () => {
  const canAlign = selectedIndices.length > 1;
  const canGroup = selectedIndices.length > 1;
  const activeObjects = getActiveObjects() || [];
  const canUngroup = selectedIndices.some(
    (idx) => activeObjects[idx]?.type === "group"
  );
  const canExplodeSvg = selectedIndices.length === 1
    && activeObjects[selectedIndices[0]]?.type === "image"
    && /\.svg$/i.test(String(activeObjects[selectedIndices[0]]?.src || "").trim());
  const canMatchSize = selectedIndices.length > 1
    && selectedIndices.every((idx) => canSizeMatchObject(activeObjects[idx]));
  const canSpaceEvenly = selectedIndices.length > 2
    && selectedIndices.every((idx) => canSizeMatchObject(activeObjects[idx]));
  const canReorder = selectedIndices.length > 0;
  const canFlip = selectedIndices.length > 0;
  const canAddRectDynamic = Boolean(getSelectedRectObject());
  const canAddLineDynamic = Boolean(getSelectedLineObject());
  const canAddEllipseDynamic = Boolean(getSelectedEllipseObject());
  const canAddTextDynamic = Boolean(getSelectedTextObject());
  const canAddButtonDynamic = Boolean(getSelectedButtonObject());
  const canAddCircleDynamic = Boolean(getSelectedCircleObject());
  const canAddPolygonDynamic = Boolean(getSelectedPolygonObject());
  const canAddGroupDynamic = Boolean(getSelectedGroupObject());
  const canAddColorDynamic = canAddRectDynamic || canAddLineDynamic || canAddEllipseDynamic || canAddTextDynamic || canAddButtonDynamic || canAddCircleDynamic || canAddPolygonDynamic || canAddGroupDynamic;
  const canAddStatesDynamic = canAddRectDynamic || canAddLineDynamic || canAddEllipseDynamic || canAddTextDynamic || canAddButtonDynamic || canAddCircleDynamic || canAddGroupDynamic;
  const canAddRotationDynamic = canAddRectDynamic || canAddLineDynamic || canAddEllipseDynamic || canAddTextDynamic || canAddButtonDynamic || canAddGroupDynamic;
  const canAddMotionDynamic = canAddRectDynamic || canAddLineDynamic || canAddEllipseDynamic || canAddTextDynamic || canAddButtonDynamic || canAddCircleDynamic || canAddGroupDynamic;
  const canOpenDynamics = canAddRectDynamic || canAddLineDynamic || canAddEllipseDynamic || canAddTextDynamic || canAddButtonDynamic || canAddGroupDynamic || canAddCircleDynamic || canAddPolygonDynamic;
  const toggleItem = (el) => {
    if (!el) return;
    const disabled = el === groupMenuBtn ? !canGroup
      : el === ungroupMenuBtn ? !canUngroup
      : !canAlign;
    el.classList.toggle("is-disabled", disabled);
  };
  const toggleSizeItem = (el) => {
    if (!el) return;
    el.classList.toggle("is-disabled", !canMatchSize);
  };
  const toggleSpaceItem = (el) => {
    if (!el) return;
    el.classList.toggle("is-disabled", !canSpaceEvenly);
  };
  const toggleReorderItem = (el) => {
    if (!el) return;
    el.classList.toggle("is-disabled", !canReorder);
  };
  const toggleFlipItem = (el) => {
    if (!el) return;
    el.classList.toggle("is-disabled", !canFlip);
  };
  const toggleDynamicMenuItem = (el, enabled) => {
    if (!el) return;
    el.classList.toggle("is-disabled", !enabled);
    el.disabled = !enabled;
  };
  if (explodeSelectedSvgBtn) {
    explodeSelectedSvgBtn.classList.toggle("is-disabled", !canExplodeSvg);
  }
  if (groupToggleBtn) {
    const activeObjects = getActiveObjects() || [];
    const isSingleGroup = selectedIndices.length === 1
      && activeObjects[selectedIndices[0]]?.type === "group";
    const shouldEnable = canGroup || isSingleGroup;
    groupToggleBtn.classList.toggle("is-disabled", !shouldEnable);
    groupToggleBtn.textContent = isSingleGroup ? "Ungroup" : "Group";
    groupToggleBtn.title = isSingleGroup ? "Ungroup selected group" : "Group selected items";
  }
  toggleItem(groupMenuBtn);
  toggleItem(ungroupMenuBtn);
  toggleItem(alignMenuLeft);
  toggleItem(alignMenuCenter);
  toggleItem(alignMenuRight);
  toggleItem(alignMenuTop);
  toggleItem(alignMenuMiddle);
  toggleItem(alignMenuBottom);
  toggleSizeItem(matchMenuWidth);
  toggleSizeItem(matchMenuHeight);
  toggleSizeItem(matchMenuSize);
  toggleSpaceItem(spaceMenuHorizontal);
  toggleSpaceItem(spaceMenuVertical);
  toggleFlipItem(flipMenuHorizontal);
  toggleFlipItem(flipMenuVertical);
  toggleReorderItem(moveToFrontMenuBtn);
  toggleReorderItem(moveToBackMenuBtn);
  toggleDynamicMenuItem(dynamicsMenuBtn, canOpenDynamics);
  toggleDynamicMenuItem(dynamicsAddVisibilityMenuBtn, canOpenDynamics);
  toggleDynamicMenuItem(dynamicsAddColorMenuBtn, canAddColorDynamic);
  toggleDynamicMenuItem(dynamicsAddStatesMenuBtn, canAddStatesDynamic);
  toggleDynamicMenuItem(dynamicsAddRotationMenuBtn, canAddRotationDynamic);
  toggleDynamicMenuItem(dynamicsAddMotionMenuBtn, canAddMotionDynamic);
};

const setMenuOpen = (isOpen) => {
  if (!menuDropdown || !menuToggleBtn) return;
  menuDropdown.classList.toggle("is-open", isOpen);
  menuToggleBtn.setAttribute("aria-expanded", isOpen ? "true" : "false");
  if (!isOpen && fileMenuFlyout && fileMenuBtn) {
    fileMenuFlyout.classList.add("is-hidden");
    fileMenuBtn.setAttribute("aria-expanded", "false");
  }
  if (!isOpen && viewMenuFlyout && viewMenuBtn) {
    viewMenuFlyout.classList.add("is-hidden");
    viewMenuBtn.setAttribute("aria-expanded", "false");
  }
  if (!isOpen && insertMenuFlyout && insertMenuBtn) {
    insertMenuFlyout.classList.add("is-hidden");
    insertMenuBtn.setAttribute("aria-expanded", "false");
  }
  if (!isOpen && dynamicsMenuFlyout && dynamicsMenuBtn) {
    dynamicsMenuFlyout.classList.add("is-hidden");
    dynamicsMenuBtn.setAttribute("aria-expanded", "false");
  }
};

const scheduleWsReconnect = () => {
  if (wsReconnectTimer) return;
  wsReconnectTimer = setTimeout(() => {
    wsReconnectTimer = null;
    connectWebSocket();
  }, 3000);
};

const normalizeTagCacheKey = (connectionId, tagName) => {
  const conn = String(connectionId || "").trim();
  const tag = String(tagName || "").trim();
  if (!conn || !tag) return "";
  return `${conn}.${tag}`;
};

const scheduleRuntimeRender = () => {
  if (wsRuntimeRenderRaf != null) return;
  wsRuntimeRenderRaf = window.requestAnimationFrame(() => {
    wsRuntimeRenderRaf = null;
    if (!isEditMode && !isEditingGestureActive() && !isKeypadOpen) {
      renderScreen();
      if (currentPopupScreenId) openPopup(currentPopupScreenId);
    }
  });
};

const normalizeWsTagKey = (connectionId, tagName) => {
  const conn = String(connectionId || "").trim();
  const tag = String(tagName || "").trim();
  if (!conn || !tag) return "";
  return `${conn}:${tag}`;
};

const collectTagKeysFromValue = (value, out, depth = 0) => {
  if (!value || depth > 10) return;
  if (Array.isArray(value)) {
    value.forEach((item) => collectTagKeysFromValue(item, out, depth + 1));
    return;
  }
  if (typeof value !== "object") return;

  const conn = value.connection_id;
  const tag = value.tag;
  if (typeof conn === "string" && typeof tag === "string") {
    const key = normalizeWsTagKey(conn, tag);
    if (key) out.add(key);
  }
  if (value.sourceType === "expression" && typeof value.expression === "string") {
    extractAutomationExpressionTagKeys(value.expression, out);
  }
  if (value.flashEnabled) {
    const rate = value.flashRate === "fast" ? "FastBlink" : "SlowBlink";
    out.add(normalizeWsTagKey("_system", `System/Clock/${rate}`));
  }

  Object.values(value).forEach((v) => {
    if (v && (typeof v === "object")) collectTagKeysFromValue(v, out, depth + 1);
  });
};

const collectViewportTargetsFromValue = (value, out, depth = 0) => {
  if (!value || depth > 10) return;
  if (Array.isArray(value)) {
    value.forEach((item) => collectViewportTargetsFromValue(item, out, depth + 1));
    return;
  }
  if (typeof value !== "object") return;

  if (value.type === "viewport") {
    const targetId = String(value.target || "").trim();
    if (targetId) out.add(targetId);
  }

  Object.values(value).forEach((v) => {
    if (v && (typeof v === "object")) collectViewportTargetsFromValue(v, out, depth + 1);
  });
};

const collectActiveWsSubscriptions = () => {
  const out = new Set();
  if (currentScreenObj) {
    collectTagKeysFromValue(currentScreenObj, out);

    // Include any loaded viewport target screens (only those already in cache).
    const targetIds = new Set();
    collectViewportTargetsFromValue(currentScreenObj, targetIds);
    targetIds.forEach((targetId) => {
      const child = screenCache.get(targetId);
      if (child) collectTagKeysFromValue(child, out);
    });
  }

  // Include popup screen if open and loaded.
  if (typeof currentPopupScreenId !== "undefined" && currentPopupScreenId) {
    const child = screenCache.get(currentPopupScreenId);
    if (child) collectTagKeysFromValue(child, out);
  }

  return Array.from(out).sort();
};

const wsTagKeyToQueryItem = (key) => {
  const raw = String(key || "");
  const sep = raw.indexOf(":");
  if (sep <= 0 || sep >= raw.length - 1) return null;
  const connection_id = raw.slice(0, sep).trim();
  const name = raw.slice(sep + 1).trim();
  if (!connection_id || !name) return null;
  return { connection_id, name };
};

const applyTagRowsToCache = (rows) => {
  let changed = false;
  (Array.isArray(rows) ? rows : []).forEach((tag) => {
    const connectionId = String(tag?.connection_id || "");
    const name = String(tag?.name || "");
    const key = normalizeTagCacheKey(connectionId, name);
    if (!key) return;
    if (Object.prototype.hasOwnProperty.call(tag, "value")) {
      tagValueCache.set(key, tag.value);
      changed = true;
    }
    if (Object.prototype.hasOwnProperty.call(tag, "quality")) {
      tagQualityCache.set(key, tag.quality);
    }
  });
  return changed;
};

const seedTagValuesForKeys = async (keys) => {
  const queryItems = Array.from(new Set(keys || []))
    .map(wsTagKeyToQueryItem)
    .filter(Boolean);
  if (!queryItems.length) return false;
  let changed = false;
  for (let i = 0; i < queryItems.length; i += 500) {
    const chunk = queryItems.slice(i, i + 500);
    const response = await fetch("/api/opc/tags/query", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      cache: "no-store",
      body: JSON.stringify({ tags: chunk })
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    changed = applyTagRowsToCache(data?.tags) || changed;
  }
  return changed;
};

const seedActiveTagValues = async () => {
  if (tagSeedRefreshInFlight) return;
  tagSeedRefreshInFlight = true;
  try {
    const changed = await seedTagValuesForKeys(collectActiveWsSubscriptions());
    if (changed && !isEditingGestureActive() && !isKeypadOpen) {
      renderScreen();
      if (currentPopupScreenId) openPopup(currentPopupScreenId);
    }
  } catch {
    // WebSocket updates remain primary; exact seeding is a best-effort catch-up path.
  } finally {
    tagSeedRefreshInFlight = false;
  }
};

const scheduleTagSeedRefresh = () => {
  if (tagSeedRefreshTimer) return;
  tagSeedRefreshTimer = setTimeout(() => {
    tagSeedRefreshTimer = null;
    seedActiveTagValues();
  }, 150);
};

const wsSendSubscribe = (tags) => {
  if (!wsConnected || !wsClient || wsClient.readyState !== WebSocket.OPEN) return;
  try {
    wsClient.send(JSON.stringify({ type: "subscribe", tags }));
  } catch {
    // ignore
  }
};

const updateWsSubscriptions = () => {
  if (!wsConnected) return;
  const tags = collectActiveWsSubscriptions();
  const fingerprint = tags.join("\n");
  if (fingerprint === wsLastSubscribeFingerprint) return;
  wsLastSubscribeFingerprint = fingerprint;
  wsSendSubscribe(tags);
};

const scheduleWsSubscribeRefresh = () => {
  if (wsSubscribeTimer) return;
  wsSubscribeTimer = setTimeout(() => {
    wsSubscribeTimer = null;
    updateWsSubscriptions();
    scheduleTagSeedRefresh();
  }, 100);
};

const connectWebSocket = () => {
  const nextUrl = getWsUrl();
  wsCurrentUrl = nextUrl;

  if (wsClient) {
    wsClient.onopen = null;
    wsClient.onclose = null;
    wsClient.onerror = null;
    wsClient.onmessage = null;
    wsClient.close();
    wsClient = null;
  }

  wsConnected = false;
  updateWsStatus();
  wsLastSubscribeFingerprint = "";

  if (!nextUrl) return;

  try {
    wsClient = new WebSocket(nextUrl);
  } catch {
    scheduleWsReconnect();
    return;
  }

  wsClient.onopen = () => {
    wsConnected = true;
    updateWsStatus();
    scheduleWsSubscribeRefresh();
  };

  wsClient.onclose = () => {
    wsConnected = false;
    updateWsStatus();
    wsLastSubscribeFingerprint = "";
    scheduleWsReconnect();
  };

  wsClient.onerror = () => {
    wsConnected = false;
    updateWsStatus();
  };

  wsClient.onmessage = (event) => {
    try {
      const payload = JSON.parse(event.data);
      if (payload?.type === "tag_update") {
        const key = normalizeTagCacheKey(payload.connection_id, payload.name);
        tagValueCache.set(key, payload.value);
        if (Object.prototype.hasOwnProperty.call(payload, "quality")) {
          tagQualityCache.set(key, payload.quality);
        }
        scheduleRuntimeRender();
      }
    } catch {
      // ignore malformed payloads
    }
  };
};

const getCssNumber = (value) => {
  const parsed = Number.parseFloat(String(value || "").replace("px", ""));
  return Number.isFinite(parsed) ? parsed : 0;
};

const isHexColor = (value) => /^#[0-9a-f]{6}$/i.test(String(value || "").trim());

const setInputValueSafe = (input, value) => {
  if (!input) return;
  if (document.activeElement === input) return;
  input.value = value;
};

const setSelectValueSafe = (select, value) => {
  if (!select) return;
  if (document.activeElement === select) return;
  select.value = value;
};

const isActiveElementWithin = (container) => {
  const active = document.activeElement;
  return Boolean(container && active && container.contains(active));
};

const setTagBindingFieldValues = (connectionInput, tagInput, binding) => {
  setInputValueSafe(connectionInput, String(binding?.connection_id || "").trim());
  setInputValueSafe(tagInput, String(binding?.tag || "").trim());
};

const ensureCombinedTagSelectValue = (select, connectionId, tagName) => {
  if (!select) return;
  const conn = String(connectionId || "").trim();
  const tag = String(tagName || "").trim();
  const combined = conn && tag ? `${conn}::${tag}` : "";
  if (!combined) {
    setSelectValueSafe(select, "");
    return;
  }
  const hasOption = Array.from(select.options || []).some((opt) => opt.value === combined);
  if (!hasOption) {
    const opt = document.createElement("option");
    opt.value = combined;
    opt.textContent = tag;
    select.appendChild(opt);
  }
  setSelectValueSafe(select, combined);
};

const blurActiveFormControl = () => {
  const el = document.activeElement;
  if (!el) return;
  const tag = el.tagName?.toLowerCase?.() || "";
  const isForm = tag === "input" || tag === "textarea" || tag === "select" || el.isContentEditable;
  if (!isForm) return;
  try { el.blur(); } catch { /* ignore */ }
};

const parseOptionalNumber = (value) => {
  const raw = String(value ?? "").trim();
  if (!raw) return null;
  const num = Number(raw);
  return Number.isFinite(num) ? num : null;
};

const getScreenSize = () => {
  const rootStyles = getComputedStyle(document.documentElement);
  const width = getCssNumber(rootStyles.getPropertyValue("--screen-width"));
  const height = getCssNumber(rootStyles.getPropertyValue("--screen-height"));
  return {
    width: width || 1920,
    height: height || 1080,
  };
};

const getViewportIds = () => {
  if (!currentScreenObj?.objects) return [];
  return currentScreenObj.objects
    .filter((obj) => obj?.type === "viewport" && obj.id)
    .map((obj) => String(obj.id));
};

const refreshViewportIdOptions = () => {
  const ids = getViewportIds();
  const fillSelect = (selectEl) => {
    if (!selectEl) return;
    const previous = selectEl.value;
    selectEl.innerHTML = "";
    const empty = document.createElement("option");
    empty.value = "";
    empty.textContent = "None";
    selectEl.appendChild(empty);
    ids.forEach((id) => {
      const opt = document.createElement("option");
      opt.value = id;
      opt.textContent = id;
      selectEl.appendChild(opt);
    });
    if (ids.includes(previous)) {
      selectEl.value = previous;
    }
  };
  fillSelect(buttonViewportSelect);
  fillSelect(groupActionViewportIdSelect);
};

const getAlarmPanelIds = () => {
  if (!currentScreenObj || !Array.isArray(currentScreenObj.objects)) return [];
  const ids = [];
  const walk = (objects) => {
    if (!Array.isArray(objects)) return;
    objects.forEach((obj) => {
      if (!obj) return;
      if (obj.type === "alarms-panel" && obj.id) ids.push(String(obj.id));
      if (obj.type === "group") walk(obj.children);
    });
  };
  walk(currentScreenObj.objects);
  return [...new Set(ids)].sort((a, b) => a.localeCompare(b));
};

const refreshAlarmPanelTargetOptions = () => {
  if (!buttonAlarmFilterTargetSelect) return;
  const previous = buttonAlarmFilterTargetSelect.value;
  buttonAlarmFilterTargetSelect.innerHTML = "";
  const all = document.createElement("option");
  all.value = "";
  all.textContent = "All alarm panels";
  buttonAlarmFilterTargetSelect.appendChild(all);
  getAlarmPanelIds().forEach((id) => {
    const opt = document.createElement("option");
    opt.value = id;
    opt.textContent = id;
    buttonAlarmFilterTargetSelect.appendChild(opt);
  });
  buttonAlarmFilterTargetSelect.value = getAlarmPanelIds().includes(previous) ? previous : "";
};

const updateButtonActionUI = (actionType) => {
  const isWriteAction = actionType === "momentary-write" || actionType === "toggle-write" || actionType === "set-write" || actionType === "prompt-write";
  const isHistoryAction = actionType === "history-back" || actionType === "history-forward";
  const isAlarmFilterAction = actionType === "alarm-filter";
  const isPromptWrite = actionType === "prompt-write";
  const showOffValue = actionType === "momentary-write" || actionType === "toggle-write";
  if (buttonTargetRow) buttonTargetRow.classList.toggle("is-hidden", isWriteAction || isHistoryAction || isAlarmFilterAction);
  if (buttonViewportRow) buttonViewportRow.classList.toggle("is-hidden", actionType !== "load-viewport");
  if (buttonWriteFields) {
    const showWrite = isWriteAction;
    buttonWriteFields.classList.toggle("is-hidden", !showWrite);
    buttonWriteFields.hidden = !showWrite;
  }
  if (buttonAlarmFilterFields) {
    buttonAlarmFilterFields.classList.toggle("is-hidden", !isAlarmFilterAction);
    buttonAlarmFilterFields.hidden = !isAlarmFilterAction;
    if (isAlarmFilterAction) refreshAlarmPanelTargetOptions();
  }
  if (buttonWriteOnRow) buttonWriteOnRow.classList.toggle("is-hidden", isPromptWrite);
  if (buttonWriteOffRow) buttonWriteOffRow.classList.toggle("is-hidden", isPromptWrite || (isWriteAction && !showOffValue));
  if (buttonWriteOnLabel) buttonWriteOnLabel.textContent = actionType === "set-write" ? "Value" : "On Value";
  if (buttonPromptDefaultRow) buttonPromptDefaultRow.classList.toggle("is-hidden", !isPromptWrite);
  if (buttonPromptMinRow) buttonPromptMinRow.classList.toggle("is-hidden", !isPromptWrite);
  if (buttonPromptMaxRow) buttonPromptMaxRow.classList.toggle("is-hidden", !isPromptWrite);
  if (buttonPromptStepRow) buttonPromptStepRow.classList.toggle("is-hidden", !isPromptWrite);
};

const refreshGroupActionScreenOptions = () => {
  if (!groupActionScreenIdSelect) return;
  const previous = groupActionScreenIdSelect.value;
  groupActionScreenIdSelect.innerHTML = "";
  const empty = document.createElement("option");
  empty.value = "";
  empty.textContent = "Select screen…";
  groupActionScreenIdSelect.appendChild(empty);
  availableScreens.forEach((screenItem) => {
    const opt = document.createElement("option");
    opt.value = screenItem.id;
    opt.textContent = screenItem.id;
    groupActionScreenIdSelect.appendChild(opt);
  });
  if (availableScreens.some((s) => s.id === previous)) {
    groupActionScreenIdSelect.value = previous;
  }
};

const setGroupActionRows = (actionType) => {
  const type = String(actionType || "");
  const hasAction = Boolean(type);
  const isLoadViewport = type === "load-viewport";
  if (groupActionViewportRow) {
    groupActionViewportRow.classList.toggle("is-hidden", !isLoadViewport);
    groupActionViewportRow.hidden = !isLoadViewport;
  }
  if (groupActionScreenRow) {
    groupActionScreenRow.classList.toggle("is-hidden", !hasAction);
    groupActionScreenRow.hidden = !hasAction;
  }
};

const createViewportId = () => {
  const ids = new Set(getViewportIds());
  let index = 1;
  while (ids.has(`vp_${index}`)) index += 1;
  return `vp_${index}`;
};

const createAlarmPanelId = () => {
  const ids = new Set(getAlarmPanelIds());
  let index = 1;
  while (ids.has(`alarm_${index}`)) index += 1;
  return `alarm_${index}`;
};

const createNumberInputId = () => {
  const ids = new Set(
    (currentScreenObj?.objects || [])
      .filter((obj) => obj?.type === "number-input" && obj.id)
      .map((obj) => String(obj.id))
  );
  while (ids.has(`ni_${nextNumberInputId}`)) nextNumberInputId += 1;
  const id = `ni_${nextNumberInputId}`;
  nextNumberInputId += 1;
  return id;
};

const createIndicatorId = () => {
  const ids = new Set(
    (currentScreenObj?.objects || [])
      .filter((obj) => obj?.type === "indicator" && obj.id)
      .map((obj) => String(obj.id))
  );
  while (ids.has(`ind_${nextIndicatorId}`)) nextIndicatorId += 1;
  const id = `ind_${nextIndicatorId}`;
  nextIndicatorId += 1;
  return id;
};

const populateTagSelect = (selectEl) => {
  if (!selectEl) return;
  const previous = selectEl.value;
  selectEl.innerHTML = "";
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = "Select tag…";
  selectEl.appendChild(placeholder);
  const groups = new Map();
  tagsCache.forEach((tag) => {
    const connectionId = String(tag.connection_id || "");
    const tagName = String(tag.name || "");
    const value = `${connectionId}::${tagName}`;
    if (!groups.has(connectionId)) groups.set(connectionId, []);
    groups.get(connectionId).push({ value, tagName });
  });
  Array.from(groups.entries()).forEach(([connectionId, entries]) => {
    const group = document.createElement("optgroup");
    group.label = connectionId || "?";
    entries.forEach((entry) => {
      const opt = document.createElement("option");
      opt.value = entry.value;
      opt.textContent = entry.tagName || "?";
      group.appendChild(opt);
    });
    selectEl.appendChild(group);
  });
  if (previous && Array.from(selectEl.options).some((opt) => opt.value === previous)) {
    selectEl.value = previous;
  }
};

const populateConnectionSelect = (selectEl) => {
  if (!selectEl) return;
  const previous = String(selectEl.value || "");
  const nextVersion = String(tagsCacheVersion);
  if (selectEl.dataset.tagsVersion === nextVersion && selectEl.options.length) {
    if (previous && Array.from(selectEl.options).some((opt) => opt.value === previous)) {
      selectEl.value = previous;
    }
    return;
  }
  const connectionIds = sortConnectionIdsForDisplay(tagsCache.map((tag) => String(tag?.connection_id || "")));
  selectEl.innerHTML = "";
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = "Select connection…";
  selectEl.appendChild(placeholder);
  connectionIds.forEach((connectionId) => {
    const opt = document.createElement("option");
    opt.value = connectionId;
    opt.textContent = connectionId;
    selectEl.appendChild(opt);
  });
  selectEl.dataset.tagsVersion = nextVersion;
  if (previous && connectionIds.includes(previous)) {
    selectEl.value = previous;
  }
};

const populateFilteredCombinedTagSelect = (selectEl, connectionId = "") => {
  if (!selectEl) return;
  const previous = String(selectEl.value || "");
  const selectedConnectionId = String(connectionId || "");
  const nextVersion = String(tagsCacheVersion);
  if (
    selectEl.dataset.tagsVersion === nextVersion
    && selectEl.dataset.connectionId === selectedConnectionId
    && selectEl.options.length
  ) {
    if (previous && Array.from(selectEl.options).some((opt) => opt.value === previous)) {
      selectEl.value = previous;
    }
    return;
  }
  selectEl.innerHTML = "";
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = "Select tag…";
  selectEl.appendChild(placeholder);
  const tags = tagsCache
    .filter((tag) => !selectedConnectionId || String(tag?.connection_id || "") === selectedConnectionId)
    .map((tag) => ({
      connectionId: String(tag?.connection_id || ""),
      tagName: String(tag?.name || "")
    }))
    .filter((tag) => tag.connectionId && tag.tagName)
    .sort((a, b) => a.tagName.localeCompare(b.tagName, undefined, { numeric: true, sensitivity: "base" }));
  tags.forEach(({ connectionId: nextConnectionId, tagName }) => {
    const opt = document.createElement("option");
    opt.value = `${nextConnectionId}::${tagName}`;
    opt.textContent = tagName;
    selectEl.appendChild(opt);
  });
  selectEl.dataset.tagsVersion = nextVersion;
  selectEl.dataset.connectionId = selectedConnectionId;
  if (previous && Array.from(selectEl.options).some((opt) => opt.value === previous)) {
    selectEl.value = previous;
  }
};

const closeTextBindingModal = () => {
  if (!textBindingOverlay) return;
  textBindingModalKey = "";
  textBindingModalObjectType = "text";
  textBindingOverlay.classList.add("is-hidden");
  textBindingOverlay.setAttribute("aria-hidden", "true");
};

const updateTextBindingProperty = (placeholderKey, patch, { clear = false } = {}) => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (selectedIndices.length !== 1) return;
  const index = selectedIndices[0];
  const obj = activeObjects[index];
  if (!obj || obj.type !== "text") return;
  const key = String(placeholderKey || "").trim();
  if (!key) return;
  recordHistory();
  const nextBindings = getTextBindingsMap(obj);
  if (clear) {
    delete nextBindings[key];
  } else {
    const merged = normalizeTextBinding({ ...(nextBindings[key] || {}), ...patch });
    if (merged) nextBindings[key] = merged;
    else delete nextBindings[key];
  }
  if (Object.keys(nextBindings).length) obj.textBindings = nextBindings;
  else delete obj.textBindings;
  delete obj.bindText;
  if (isTextAutoSize(obj)) {
    const autoPatch = autosizeTextObject(obj);
    if (autoPatch) Object.assign(obj, autoPatch);
  }
  if (textBindingModalKey && !getTextPlaceholderKeys(obj.text || "").includes(textBindingModalKey)) {
    closeTextBindingModal();
  }
  renderScreen();
  syncEditorFromScreen();
  setDirty(true);
};

const updateButtonLabelBindingProperty = (placeholderKey, patch, { clear = false } = {}) => {
  const activeObjects = getActiveObjects();
  if (!activeObjects || !Array.isArray(activeObjects)) return;
  if (selectedIndices.length !== 1) return;
  const index = selectedIndices[0];
  const obj = activeObjects[index];
  if (!obj || obj.type !== "button") return;
  const key = String(placeholderKey || "").trim();
  if (!key) return;
  recordHistory();
  const nextBindings = getButtonLabelBindingsMap(obj);
  if (clear) {
    delete nextBindings[key];
  } else {
    const merged = normalizeTextBinding({ ...(nextBindings[key] || {}), ...patch });
    if (merged) nextBindings[key] = merged;
    else delete nextBindings[key];
  }
  if (Object.keys(nextBindings).length) obj.labelBindings = nextBindings;
  else delete obj.labelBindings;
  delete obj.bindLabel;
  if (textBindingModalObjectType === "button" && textBindingModalKey && !getTextPlaceholderKeys(obj.label || "").includes(textBindingModalKey)) {
    closeTextBindingModal();
  }
  renderScreen();
  syncEditorFromScreen();
  setDirty(true);
};

const renderTextBindingRows = (obj) => {
  if (!textBindingRows) return;
  textBindingRows.textContent = "";
  const placeholderKeys = getTextPlaceholderKeys(obj?.text || "");
  if (!placeholderKeys.length) {
    const empty = document.createElement("div");
    empty.className = "text-binding-summary";
    empty.textContent = "No placeholders in text.";
    textBindingRows.appendChild(empty);
    return;
  }
  const bindings = getTextBindingsMap(obj);
  placeholderKeys.forEach((key) => {
    textBindingRows.appendChild(createInlineTextBindingRow({
      key,
      binding: bindings[key],
      objectType: "text"
    }));
  });
};

const renderButtonLabelBindingRows = (obj) => {
  if (!buttonLabelBindingRows) return;
  buttonLabelBindingRows.textContent = "";
  const placeholderKeys = getTextPlaceholderKeys(obj?.label || "");
  if (!placeholderKeys.length) {
    const empty = document.createElement("div");
    empty.className = "text-binding-summary";
    empty.textContent = "No placeholders in label.";
    buttonLabelBindingRows.appendChild(empty);
    return;
  }
  const bindings = getButtonLabelBindingsMap(obj);
  placeholderKeys.forEach((key) => {
    buttonLabelBindingRows.appendChild(createInlineTextBindingRow({
      key,
      binding: bindings[key],
      objectType: "button"
    }));
  });
};

const openTextBindingModal = (placeholderKey, objectType = "text") => {
  if (!textBindingOverlay) return;
  const activeObjects = getActiveObjects();
  const obj = selectedIndices.length === 1 ? activeObjects?.[selectedIndices[0]] : null;
  if (!obj || obj.type !== objectType) return;
  const key = String(placeholderKey || "").trim();
  if (!key) return;
  const binding = objectType === "button" ? (getButtonLabelBindingsMap(obj)[key] || null) : (getTextBindingsMap(obj)[key] || null);
  textBindingModalKey = key;
  textBindingModalObjectType = objectType;
  if (textBindingTitle) textBindingTitle.textContent = `${objectType === "button" ? "Button Label" : "Text"} Binding {${key}}`;
  setTagBindingFieldValues(textBindingConnectionInput, textBindingTagInput, binding);
  setInputValueSafe(textBindingDigitsInput, binding?.digits ?? "");
  if (textBindingPadZerosInput) {
    textBindingPadZerosInput.checked = binding?.padZeros === true || String(binding?.padZeros || "").trim().toLowerCase() === "true";
  }
  setInputValueSafe(textBindingDecimalsInput, Number.isFinite(Number(binding?.decimals)) ? Number(binding.decimals) : 0);
  setInputValueSafe(textBindingMultiplierInput, Number.isFinite(Number(binding?.multiplier)) ? Number(binding.multiplier) : 1);
  textBindingOverlay.classList.remove("is-hidden");
  textBindingOverlay.setAttribute("aria-hidden", "false");
  if (textBindingTagInput) requestAnimationFrame(() => textBindingTagInput.focus());
};

